-- SQL013: inactive canonical authority foundation. REVIEWED SOURCE; qualification is recorded separately.
-- Governing candidate5355d60247450b7ec4dcd3dd31405d22f53122449274a78300a82498ab9c0727.
-- No runtime authority grants. Owner fixtures are integrity probes, not administered access.
-- Every public interface is native-owner-only; SQL001--012 remain immutable.
DO $$ BEGIN
 IF session_user<>current_user OR NOT EXISTS(SELECT 1 FROM gc_authn.installation_root r WHERE r.owner_role_oid=session_user::regrole::oid AND r.owner_role_name=session_user AND r.database_oid=(SELECT oid FROM pg_database WHERE datname=current_database())) THEN RAISE EXCEPTION 'AUTHORITY_FOUNDATION_EXECUTOR_REJECTED' USING ERRCODE='42501'; END IF;
END $$;
CREATE SCHEMA gc_authority;
REVOKE ALL ON SCHEMA gc_authority FROM PUBLIC;
-- Per-schema defaults are additive in PostgreSQL. These global creator defaults
-- remove implicit PUBLIC access for future functions/types in this database;
-- they do not modify any existing object ACL, including SQL001--012 objects.
-- Future trusted migrations must explicitly grant each intended capability.
ALTER DEFAULT PRIVILEGES REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
ALTER DEFAULT PRIVILEGES REVOKE USAGE ON TYPES FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA gc_authority REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA gc_authority REVOKE USAGE ON TYPES FROM PUBLIC;
CREATE FUNCTION gc_authority.require(ok boolean,code text DEFAULT '22023') RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION '%', CASE code WHEN '42501' THEN 'AUTHORITY_FOUNDATION_EXECUTOR_REJECTED' WHEN '28000' THEN 'AUTHORITY_FOUNDATION_SESSION_REJECTED' WHEN '40001' THEN 'AUTHORITY_FOUNDATION_VERSION_CONFLICT' WHEN '54000' THEN 'AUTHORITY_FOUNDATION_PROFILE_LIMIT' WHEN '23514' THEN 'AUTHORITY_FOUNDATION_INTEGRITY' WHEN '57014' THEN 'AUTHORITY_FOUNDATION_DEADLINE' ELSE 'AUTHORITY_FOUNDATION_INPUT_INVALID' END USING ERRCODE=code; END IF;
END $$;
CREATE FUNCTION gc_authority.tick() RETURNS void LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog AS $$ BEGIN PERFORM gc_authority.require(clock_timestamp()<transaction_timestamp()+interval '30 seconds','57014'); END $$;
CREATE FUNCTION gc_authority.utc(t timestamptz) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT to_char(t AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') $$;
CREATE FUNCTION gc_authority.valid_time(t timestamptz) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT t IS NOT NULL AND isfinite(t) AND t>='0001-01-01 00:00:00+00'::timestamptz AND t<'10000-01-01 00:00:00+00'::timestamptz AND t=date_trunc('milliseconds',t) $$;
CREATE FUNCTION gc_authority.valid_uuid(u uuid) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT u IS NOT NULL AND u<>'00000000-0000-0000-0000-000000000000'::uuid $$;
-- JavaScript compares UTF-16 code units, not database locale or UTF-8 bytes.
CREATE FUNCTION gc_authority.sortkey(s text) RETURNS bytea LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$ DECLARE b bytea:=''::bytea;c integer;i integer; BEGIN
 FOR i IN 1..char_length(s) LOOP c:=ascii(substr(s,i,1)); IF c>65535 THEN c:=c-65536;b:=b||decode(lpad(to_hex(55296+c/1024),4,'0')||lpad(to_hex(56320+c%1024),4,'0'),'hex'); ELSE b:=b||decode(lpad(to_hex(c),4,'0'),'hex');END IF;END LOOP;RETURN b;END $$;
CREATE FUNCTION gc_authority.canonical(v jsonb) RETURNS text LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$ DECLARE r text; BEGIN
 CASE jsonb_typeof(v) WHEN 'object' THEN SELECT '{'||coalesce(string_agg(to_jsonb(key)::text||':'||gc_authority.canonical(value),',' ORDER BY gc_authority.sortkey(key)),'')||'}' INTO r FROM jsonb_each(v);
 WHEN 'array' THEN SELECT '['||coalesce(string_agg(gc_authority.canonical(value),',' ORDER BY ord),'')||']' INTO r FROM jsonb_array_elements(v) WITH ORDINALITY e(value,ord);
 WHEN 'number' THEN PERFORM gc_authority.require((v#>>'{}')::numeric=trunc((v#>>'{}')::numeric) AND abs((v#>>'{}')::numeric)<=9007199254740991);r:=trunc((v#>>'{}')::numeric)::text;
 ELSE r:=v::text;END CASE;RETURN r;END $$;
CREATE FUNCTION gc_authority.hash(v jsonb) RETURNS text LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$ SELECT encode(sha256(convert_to(gc_authority.canonical(v),'UTF8')),'hex') $$;
-- Duplicate-preserving json traversal precedes every raw text -> jsonb conversion.
CREATE FUNCTION gc_authority.raw_walk(v json,depth integer DEFAULT 1) RETURNS bigint LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE x record;n bigint:=1; BEGIN
 PERFORM gc_authority.require(depth<=32,'54000');
 IF json_typeof(v)='object' THEN PERFORM gc_authority.require(NOT EXISTS(SELECT key FROM json_each(v) GROUP BY key HAVING count(*)>1)); FOR x IN SELECT key,value FROM json_each(v) LOOP PERFORM gc_authority.require(x.key !~ '[[:cntrl:]]');n:=n+gc_authority.raw_walk(x.value,depth+1);PERFORM gc_authority.require(n<=262144,'54000');END LOOP;
 ELSIF json_typeof(v)='array' THEN FOR x IN SELECT value FROM json_array_elements(v) LOOP n:=n+gc_authority.raw_walk(x.value,depth+1);PERFORM gc_authority.require(n<=262144,'54000');END LOOP;
 ELSIF json_typeof(v)='number' THEN PERFORM gc_authority.require(v::text !~ '^-0([.]0*)?([eE][+-]?[0-9]+)?$' AND v::text::numeric=trunc(v::text::numeric) AND abs(v::text::numeric)<=9007199254740991);
 ELSIF json_typeof(v)='string' THEN PERFORM gc_authority.require((v#>>'{}') !~ '[[:cntrl:]]');END IF;RETURN n;END $$;
CREATE FUNCTION gc_authority.parse(raw text,max_bytes integer DEFAULT 8388608) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE j json;BEGIN
 PERFORM gc_authority.require(raw IS NOT NULL AND octet_length(raw)<=max_bytes,'54000');j:=raw::json;PERFORM gc_authority.raw_walk(j);RETURN j::jsonb;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR untranslatable_character THEN RAISE EXCEPTION 'AUTHORITY_FOUNDATION_INPUT_INVALID' USING ERRCODE='22023';END $$;
CREATE FUNCTION gc_authority.json_measure(v jsonb,depth integer DEFAULT 1) RETURNS bigint[] LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE x jsonb;m bigint[];n bigint:=1;d bigint:=depth;BEGIN
 PERFORM gc_authority.require(depth<=32,'54000');IF jsonb_typeof(v) IN('object','array') THEN FOR x IN SELECT value FROM jsonb_each(CASE WHEN jsonb_typeof(v)='object' THEN v ELSE '{}'::jsonb END) UNION ALL SELECT value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v)='array' THEN v ELSE '[]'::jsonb END) LOOP m:=gc_authority.json_measure(x,depth+1);n:=n+m[1];d:=greatest(d,m[2]);PERFORM gc_authority.require(n<=262144,'54000');END LOOP;END IF;RETURN ARRAY[n,d];END $$;
