CREATE FUNCTION gc_authority.item_key(v jsonb,k text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT CASE k WHEN 'scalar' THEN v#>>'{}' WHEN 'id' THEN v->>'id' WHEN 'slot' THEN v->>'slot' WHEN 'action' THEN v->>'action' WHEN 'subject' THEN (v->>'kind')||':'||(v->>'id') WHEN 'role' THEN (v->>'roleId')||'@'||lpad(v->>'version',10,'0') WHEN 'ref' THEN (v#>>'{ref,id}')||'@'||(v#>>'{ref,version}') WHEN 'prerequisite' THEN (v->>'action')||':'||(v->>'resource') WHEN 'intent' THEN (v->>'resourceKind')||':'||(v->>'subjectKind') WHEN 'projection' THEN (v->>'projectionId')||'@'||(v->>'version')||':'||(v->>'fieldId')||':'||(v->>'resourceKind')||':'||(v->>'path') ELSE gc_authority.canonical(v) END $$;
CREATE FUNCTION gc_authority.normalize(v jsonb,spec jsonb,fields jsonb DEFAULT NULL,depth integer DEFAULT 1) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE s jsonb:=spec;r jsonb:='{}';x record;n jsonb;k text;seen text[]:='{}';typ text;str text;
BEGIN
 PERFORM gc_authority.require(depth<=32,'54000');
 IF jsonb_typeof(s)='string' THEN s:=gc_authority.grammar()->(s#>>'{}');PERFORM gc_authority.require(s IS NOT NULL);END IF;
 IF s ? 'nullable' THEN IF v='null'::jsonb THEN RETURN v;END IF;RETURN gc_authority.normalize(v,s->'nullable',fields,depth);END IF;
 IF s ? 'literal' THEN PERFORM gc_authority.require(v=s->'literal');RETURN v;END IF;
 IF s ? 'enum' THEN PERFORM gc_authority.require(jsonb_typeof(v)='string' AND (s->'enum') @> jsonb_build_array(v));RETURN v;END IF;
 IF s ? 'integer' THEN PERFORM gc_authority.require(jsonb_typeof(v)='number');PERFORM gc_authority.require((v#>>'{}')::numeric=trunc((v#>>'{}')::numeric) AND (v#>>'{}')::numeric BETWEEN (s#>>'{integer,0}')::numeric AND (s#>>'{integer,1}')::numeric);RETURN to_jsonb((v#>>'{}')::bigint);END IF;
 IF s ? 'scalar' THEN typ:=s->>'scalar';
  IF typ='boolean' THEN PERFORM gc_authority.require(jsonb_typeof(v)='boolean');RETURN v;END IF;
  IF typ='version' THEN RETURN gc_authority.normalize(v,'{"integer":[1,2147483647]}',fields,depth);END IF;
  PERFORM gc_authority.require(jsonb_typeof(v)='string');str:=v#>>'{}';PERFORM gc_authority.require(str !~ '[[:cntrl:]]');
  CASE typ WHEN 'uuid' THEN PERFORM gc_authority.require(str ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND str<>'00000000-0000-0000-0000-000000000000');
  WHEN 'digest' THEN PERFORM gc_authority.require(str ~ '^[0-9a-f]{64}$');
  WHEN 'counter' THEN PERFORM gc_authority.require(str ~ '^[1-9][0-9]*$' AND length(str)<=19 AND str::numeric<=9223372036854775807);
  WHEN 'utc' THEN PERFORM gc_authority.require(str ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' AND gc_authority.valid_time(str::timestamptz) AND gc_authority.utc(str::timestamptz)=str);
  WHEN 'field' THEN PERFORM gc_authority.require(length(str)>0 AND octet_length(str)<=256 AND (fields IS NULL OR fields @> jsonb_build_array(v)));
  WHEN 'handle' THEN PERFORM gc_authority.require(length(str)>0);
  WHEN 'text' THEN NULL;ELSE PERFORM gc_authority.require(false);END CASE;RETURN v;
 END IF;
 IF s ? 'tag' THEN PERFORM gc_authority.require(jsonb_typeof(v)='object');k:=v->>(s->>'tag');PERFORM gc_authority.require((s->'variants') ? k);RETURN gc_authority.normalize(v,s->'variants'->k,fields,depth);END IF;
 IF s ? 'object' THEN PERFORM gc_authority.require(jsonb_typeof(v)='object' AND (SELECT array_agg(key ORDER BY key) FROM jsonb_each(v)) IS NOT DISTINCT FROM (SELECT array_agg(key ORDER BY key) FROM jsonb_each(s->'object')));
  FOR x IN SELECT key,value FROM jsonb_each(s->'object') LOOP r:=r||jsonb_build_object(x.key,gc_authority.normalize(v->x.key,x.value,fields,depth+1));END LOOP;
  IF spec='"validity"'::jsonb THEN PERFORM gc_authority.require(r->>'notBefore' IS NULL OR r->>'expiresAt' IS NULL OR (r->>'notBefore')::timestamptz<(r->>'expiresAt')::timestamptz);END IF;RETURN r;
 END IF;
 IF s ? 'array' THEN PERFORM gc_authority.require(jsonb_typeof(v)='array');PERFORM gc_authority.require(jsonb_array_length(v) BETWEEN (s->>'min')::int AND (s->>'max')::int,'54000');r:='[]';
  FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP n:=gc_authority.normalize(x.value,s->'array',fields,depth+1);IF s->>'key'<>'' THEN k:=gc_authority.item_key(n,s->>'key');PERFORM gc_authority.require(NOT k=ANY(seen));seen:=array_append(seen,k);END IF;r:=r||jsonb_build_array(n);END LOOP;
  IF s->>'key'<>'' THEN SELECT coalesce(jsonb_agg(value ORDER BY gc_authority.sortkey(gc_authority.item_key(value,s->>'key'))),'[]') INTO r FROM jsonb_array_elements(r);END IF;RETURN r;
 END IF;PERFORM gc_authority.require(false);RETURN NULL;
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow OR invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'AUTHORITY_FOUNDATION_INPUT_INVALID' USING ERRCODE='22023';END $$;
CREATE FUNCTION gc_authority.registry(raw text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE r jsonb;x jsonb;y jsonb;a jsonb;adapter jsonb;family text;expected text;branches jsonb:='{"service-dispatch":"scan-job:dispatch","service-claim":"scan-job:claim","service-metadata":"source:metadata.scan","service-secret":"secret:resolve","service-complete":"scan-job:complete","service-fail":"scan-job:fail","service-project-consume":"projection:consume","service-project-write":"projection:write","service-audit":"audit:append","service-outbox":"outbox:append"}';
BEGIN
 r:=gc_authority.normalize(gc_authority.parse(raw),'"registry"');PERFORM gc_authority.require(r->>'digest'=gc_authority.hash(r-'digest'));
 PERFORM gc_authority.require((SELECT coalesce(sum(octet_length(value#>>'{}')),0)<=131072 AND coalesce(max(octet_length(value#>>'{}')),0)<=256 FROM jsonb_array_elements(r->'fields')),'54000');
 FOR x IN SELECT value FROM jsonb_array_elements(r->'actions') LOOP family:=CASE WHEN x->>'action'=ANY(gc_authority.field_actions()) THEN 'field' WHEN x->>'action'=ANY(gc_authority.service_actions()) THEN 'service' ELSE 'human' END;PERFORM gc_authority.require(x->>'family'=family);END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(r->'adapters') LOOP SELECT value INTO a FROM jsonb_array_elements(r->'actions') WHERE value->>'action'=x->>'action';PERFORM gc_authority.require((a->'resourceKinds') @> (x->'resourceKinds'));
  IF x->>'branch' LIKE 'human-%' THEN PERFORM gc_authority.require(a->>'family'='human');ELSIF x->>'branch'='field' THEN PERFORM gc_authority.require(a->>'family'='field');ELSIF x->>'branch'='intent-guard' THEN PERFORM gc_authority.require(a->>'family'<>'field');ELSIF x->>'branch'='service-terminal-replay' THEN PERFORM gc_authority.require(x->>'action' IN('scan-job:claim','scan-job:complete','scan-job:fail'));ELSE PERFORM gc_authority.require(x->>'action'=branches->>(x->>'branch'));END IF;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(r->'intentContexts') LOOP SELECT value INTO adapter FROM jsonb_array_elements(r->'adapters') WHERE value->>'id'=x->>'guardAdapterId';SELECT value INTO a FROM jsonb_array_elements(r->'actions') WHERE value->>'action'=x->>'denyContextAction';PERFORM gc_authority.require(adapter->>'branch'='intent-guard' AND adapter->>'action'=x->>'denyContextAction' AND (adapter->'resourceKinds') @> jsonb_build_array(x->'resourceKind') AND a->>'family'=x->>'subjectKind');END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(r->'projections') LOOP PERFORM gc_authority.require((r->'fields') @> jsonb_build_array(x->'fieldId') AND x->>'registrationHash'=gc_authority.hash(x-'registrationHash') AND jsonb_array_length(x->'prerequisites')>0);family:=NULL;
  FOR y IN SELECT value FROM jsonb_array_elements(x->'prerequisites') LOOP SELECT value INTO a FROM jsonb_array_elements(r->'actions') WHERE value->>'action'=y->>'action';PERFORM gc_authority.require(a->>'family'<>'field' AND (family IS NULL OR family=a->>'family') AND y->>'resource'=CASE x->>'path' WHEN 'direct' THEN 'field-owner' ELSE 'reference-parent' END AND (y->>'resource'<>'field-owner' OR (a->'resourceKinds') @> jsonb_build_array(x->'resourceKind')));family:=a->>'family';END LOOP;
 END LOOP;RETURN r;
END $$;
CREATE FUNCTION gc_authority.expression_stats(v jsonb,depth integer DEFAULT 1) RETURNS integer[] LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE c jsonb;n integer:=1;m integer[];d integer:=depth; BEGIN PERFORM gc_authority.require(depth<=8,'54000');IF v->>'op' IN('all','any') THEN FOR c IN SELECT value FROM jsonb_array_elements(v->'children') LOOP m:=gc_authority.expression_stats(c,depth+1);n:=n+m[1];d:=greatest(d,m[2]);END LOOP;END IF;PERFORM gc_authority.require(n<=128,'54000');RETURN ARRAY[n,d];END $$;
CREATE FUNCTION gc_authority.policy(raw text,fields jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE p jsonb;r jsonb;n integer:=0;m integer[];BEGIN
 p:=gc_authority.normalize(gc_authority.parse(raw,65536),'"policy"',fields);PERFORM gc_authority.require(NOT EXISTS(SELECT value->>'id' FROM jsonb_array_elements(p->'rules') GROUP BY value->>'id' HAVING count(*)>1));PERFORM gc_authority.require(octet_length(gc_authority.canonical(p))<=65536,'54000');FOR r IN SELECT value FROM jsonb_array_elements(p->'rules') LOOP
 PERFORM gc_authority.require((r->'fields'='null'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(r->'actions') a WHERE a=ANY(gc_authority.field_actions()))) OR (r->'fields'<>'null'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(r->'actions') a WHERE NOT a=ANY(gc_authority.field_actions()))));m:=gc_authority.expression_stats(r->'when');n:=n+m[1];PERFORM gc_authority.require(n<=128,'54000');END LOOP;RETURN p;
END $$;
CREATE TABLE gc_authority.foundation_root(singleton boolean PRIMARY KEY CHECK(singleton),database_oid oid NOT NULL,owner_role_oid oid NOT NULL,owner_role_name name NOT NULL,contract_hash text NOT NULL CHECK(contract_hash ~ '^[0-9a-f]{64}$'),installed_at timestamptz NOT NULL CHECK(gc_authority.valid_time(installed_at)),mode text NOT NULL CHECK(mode='inactive'));
INSERT INTO gc_authority.foundation_root SELECT true,database_oid,owner_role_oid,owner_role_name,'5355d60247450b7ec4dcd3dd31405d22f53122449274a78300a82498ab9c0727',date_trunc('milliseconds',clock_timestamp()),'inactive' FROM gc_authn.installation_root;
CREATE FUNCTION gc_authority.owner_check() RETURNS void LANGUAGE plpgsql STABLE SET search_path=pg_catalog,gc_authority,pg_temp AS $$ BEGIN PERFORM gc_authority.require(session_user=current_user AND EXISTS(SELECT 1 FROM gc_authority.foundation_root r JOIN gc_authn.installation_root a USING(database_oid,owner_role_oid,owner_role_name) WHERE r.singleton AND a.singleton AND r.owner_role_oid=session_user::regrole::oid AND r.owner_role_name=session_user AND r.database_oid=(SELECT oid FROM pg_database WHERE datname=current_database()) AND r.mode='inactive'),'42501');END $$;
CREATE TABLE gc_authority.installation_receipts(id uuid PRIMARY KEY CHECK(gc_authority.valid_uuid(id)),request_id uuid NOT NULL UNIQUE CHECK(gc_authority.valid_uuid(request_id)),operation text NOT NULL CHECK(operation IN('registry-install','tenant-initialize')),target_id uuid NOT NULL CHECK(gc_authority.valid_uuid(target_id)),manifest_encoding bytea NOT NULL,manifest_hash text NOT NULL UNIQUE CHECK(manifest_hash ~ '^[0-9a-f]{64}$'),recorded_at timestamptz NOT NULL CHECK(gc_authority.valid_time(recorded_at)),database_oid oid NOT NULL,owner_role_oid oid NOT NULL,release_reference text NOT NULL,operator_reference text NOT NULL);
CREATE TABLE gc_authority.registries(id uuid NOT NULL CHECK(gc_authority.valid_uuid(id)),version integer NOT NULL CHECK(version>0),digest text NOT NULL UNIQUE CHECK(digest ~ '^[0-9a-f]{64}$'),registry_document text NOT NULL CHECK(octet_length(registry_document)<=8388608),canonical_bytes bigint NOT NULL CHECK(canonical_bytes BETWEEN 1 AND 8388608),json_nodes bigint NOT NULL CHECK(json_nodes BETWEEN 1 AND 262144),installed_by uuid NOT NULL REFERENCES gc_authority.installation_receipts,installed_at timestamptz NOT NULL CHECK(gc_authority.valid_time(installed_at)),PRIMARY KEY(id,version),UNIQUE(id,version,digest));
CREATE TABLE gc_authority.tenant_heads(tenant_id uuid PRIMARY KEY REFERENCES public.tenants,generation bigint NOT NULL CHECK(generation>0),authority_epoch bigint NOT NULL CHECK(authority_epoch>0),registry_id uuid NOT NULL,registry_version integer NOT NULL,registry_digest text NOT NULL,initialized_by uuid NOT NULL REFERENCES gc_authority.installation_receipts,initialized_at timestamptz NOT NULL CHECK(gc_authority.valid_time(initialized_at)),mode text NOT NULL CHECK(mode='inactive'),FOREIGN KEY(registry_id,registry_version,registry_digest) REFERENCES gc_authority.registries(id,version,digest));
CREATE TABLE gc_authority.identity_heads(identity_id uuid PRIMARY KEY CHECK(gc_authority.valid_uuid(identity_id)),revision bigint NOT NULL CHECK(revision>0),present boolean NOT NULL,canonical_issuer text,canonical_subject text,active boolean NOT NULL,changed_at timestamptz NOT NULL CHECK(gc_authority.valid_time(changed_at)),row_digest text NOT NULL CHECK(row_digest ~ '^[0-9a-f]{64}$'),CHECK((present AND canonical_issuer IS NOT NULL AND canonical_subject IS NOT NULL) OR (NOT present AND canonical_issuer IS NULL AND canonical_subject IS NULL AND NOT active)));
CREATE TABLE gc_authority.tenant_member_heads(tenant_id uuid NOT NULL REFERENCES public.tenants,identity_id uuid NOT NULL REFERENCES gc_authority.identity_heads,membership_id uuid NOT NULL UNIQUE CHECK(gc_authority.valid_uuid(membership_id)),revision integer NOT NULL CHECK(revision>0),present boolean NOT NULL,active boolean NOT NULL,changed_at timestamptz NOT NULL CHECK(gc_authority.valid_time(changed_at)),row_digest text NOT NULL CHECK(row_digest ~ '^[0-9a-f]{64}$'),PRIMARY KEY(tenant_id,identity_id),UNIQUE(tenant_id,membership_id),CHECK(present OR NOT active));
CREATE TABLE gc_authority.definition_heads(tenant_id uuid NOT NULL REFERENCES gc_authority.tenant_heads,kind text NOT NULL CHECK(kind IN('policy','role','responsibility-type','group')),id uuid NOT NULL CHECK(gc_authority.valid_uuid(id)),key text NOT NULL CHECK(length(key)>0 AND key !~ '[[:cntrl:]]'),definition_version integer NOT NULL CHECK(definition_version>0),head_version integer NOT NULL CHECK(head_version>0),state text NOT NULL CHECK(state IN('active','retired')),changed_at timestamptz NOT NULL CHECK(gc_authority.valid_time(changed_at)),PRIMARY KEY(tenant_id,kind,id),UNIQUE(tenant_id,id),UNIQUE(tenant_id,kind,key));
CREATE TABLE gc_authority.definition_versions(tenant_id uuid NOT NULL,kind text NOT NULL,id uuid NOT NULL,version integer NOT NULL CHECK(version>0),label text NOT NULL CHECK(length(label) BETWEEN 1 AND 200 AND label !~ '[[:cntrl:]]'),description text NOT NULL CHECK(length(description)<=4000 AND description !~ '[[:cntrl:]]'),semantic_hash text NOT NULL CHECK(semantic_hash ~ '^[0-9a-f]{64}$'),created_at timestamptz NOT NULL CHECK(gc_authority.valid_time(created_at)),created_by uuid NOT NULL REFERENCES gc_authority.identity_heads,PRIMARY KEY(tenant_id,kind,id,version),FOREIGN KEY(tenant_id,kind,id) REFERENCES gc_authority.definition_heads DEFERRABLE INITIALLY DEFERRED);
ALTER TABLE gc_authority.definition_heads ADD FOREIGN KEY(tenant_id,kind,id,definition_version) REFERENCES gc_authority.definition_versions(tenant_id,kind,id,version) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE gc_authority.policy_versions(tenant_id uuid NOT NULL,policy_id uuid NOT NULL,version integer NOT NULL,definition_kind text NOT NULL DEFAULT 'policy' CHECK(definition_kind='policy'),policy_document text NOT NULL CHECK(octet_length(policy_document)<=65536),policy_hash text NOT NULL CHECK(policy_hash ~ '^[0-9a-f]{64}$'),canonical_bytes bigint NOT NULL CHECK(canonical_bytes BETWEEN 1 AND 65536),rule_count integer NOT NULL CHECK(rule_count BETWEEN 1 AND 128),expression_node_count integer NOT NULL CHECK(expression_node_count BETWEEN 1 AND 128),PRIMARY KEY(tenant_id,policy_id,version),UNIQUE(tenant_id,policy_id,version,policy_hash),FOREIGN KEY(tenant_id,definition_kind,policy_id,version) REFERENCES gc_authority.definition_versions DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE gc_authority.role_policy_pins(tenant_id uuid NOT NULL,role_id uuid NOT NULL,role_version integer NOT NULL,role_kind text NOT NULL DEFAULT 'role' CHECK(role_kind='role'),ordinal integer NOT NULL CHECK(ordinal BETWEEN 0 AND 31),policy_id uuid NOT NULL,policy_version integer NOT NULL,policy_hash text NOT NULL,PRIMARY KEY(tenant_id,role_id,role_version,ordinal),UNIQUE(tenant_id,role_id,role_version,policy_id,policy_version,policy_hash),FOREIGN KEY(tenant_id,role_kind,role_id,role_version) REFERENCES gc_authority.definition_versions DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(tenant_id,policy_id,policy_version,policy_hash) REFERENCES gc_authority.policy_versions(tenant_id,policy_id,version,policy_hash) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE gc_authority.responsibility_role_pins(tenant_id uuid NOT NULL,type_id uuid NOT NULL,type_version integer NOT NULL,type_kind text NOT NULL DEFAULT 'responsibility-type' CHECK(type_kind='responsibility-type'),role_id uuid,role_version integer,PRIMARY KEY(tenant_id,type_id,type_version),CHECK((role_id IS NULL)=(role_version IS NULL)),FOREIGN KEY(tenant_id,type_kind,type_id,type_version) REFERENCES gc_authority.definition_versions DEFERRABLE INITIALLY DEFERRED);
-- The literal role discriminant is enforced by the deferred normalized companion guard.
CREATE TABLE gc_authority.policy_deny_intents(tenant_id uuid NOT NULL,policy_id uuid NOT NULL,policy_version integer NOT NULL,policy_hash text NOT NULL,rule_id uuid NOT NULL CHECK(gc_authority.valid_uuid(rule_id)),registry_id uuid NOT NULL,registry_version integer NOT NULL,registry_digest text NOT NULL,resource_kinds text[] NOT NULL,expanded_actions text[] NOT NULL,PRIMARY KEY(tenant_id,policy_id,policy_version,rule_id),FOREIGN KEY(tenant_id,policy_id,policy_version,policy_hash) REFERENCES gc_authority.policy_versions(tenant_id,policy_id,version,policy_hash) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(registry_id,registry_version,registry_digest) REFERENCES gc_authority.registries(id,version,digest));
CREATE TABLE gc_authority.group_memberships(tenant_id uuid NOT NULL,id uuid NOT NULL CHECK(gc_authority.valid_uuid(id)),issuance_version integer NOT NULL DEFAULT 1 CHECK(issuance_version=1),group_id uuid NOT NULL,group_kind text NOT NULL DEFAULT 'group' CHECK(group_kind='group'),identity_id uuid NOT NULL REFERENCES gc_authority.identity_heads,not_before timestamptz,expires_at timestamptz,created_by uuid NOT NULL REFERENCES gc_authority.identity_heads,created_at timestamptz NOT NULL CHECK(gc_authority.valid_time(created_at)),head_version integer NOT NULL CHECK(head_version>0),state text NOT NULL CHECK(state IN('active','revoked')),changed_at timestamptz NOT NULL CHECK(gc_authority.valid_time(changed_at)),PRIMARY KEY(tenant_id,id,issuance_version),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,group_kind,group_id) REFERENCES gc_authority.definition_heads, CHECK((not_before IS NULL OR gc_authority.valid_time(not_before)) AND (expires_at IS NULL OR gc_authority.valid_time(expires_at)) AND (not_before IS NULL OR expires_at IS NULL OR not_before<expires_at)));
CREATE INDEX authority_membership_subject ON gc_authority.group_memberships(tenant_id,identity_id,group_id) WHERE state='active';
CREATE TABLE gc_authority.grant_heads(tenant_id uuid NOT NULL REFERENCES gc_authority.tenant_heads,id uuid NOT NULL CHECK(gc_authority.valid_uuid(id)),issuance_version integer NOT NULL DEFAULT 1 CHECK(issuance_version=1),kind text NOT NULL CHECK(kind IN('ordinary-role','responsibility','delegation','elevation')),issuer_identity_id uuid NOT NULL REFERENCES gc_authority.identity_heads,beneficiary_kind text NOT NULL CHECK(beneficiary_kind IN('human','group')),beneficiary_id uuid NOT NULL CHECK(gc_authority.valid_uuid(beneficiary_id)),scope_kind text NOT NULL CHECK(scope_kind IN('tenant','domain','resource')),scope_tenant_id uuid NOT NULL,domain_id uuid,include_descendants boolean,resource_kind text,resource_id uuid,not_before timestamptz,expires_at timestamptz,effect_ceiling jsonb NOT NULL,delegable_ceiling jsonb,control_ceiling jsonb,registry_id uuid NOT NULL,registry_version integer NOT NULL,registry_digest text NOT NULL,created_at timestamptz NOT NULL CHECK(gc_authority.valid_time(created_at)),created_by uuid NOT NULL REFERENCES gc_authority.identity_heads,head_version integer NOT NULL CHECK(head_version>0),state text NOT NULL CHECK(state IN('active','revoked')),changed_at timestamptz NOT NULL CHECK(gc_authority.valid_time(changed_at)),PRIMARY KEY(tenant_id,id,issuance_version),UNIQUE(tenant_id,id),FOREIGN KEY(registry_id,registry_version,registry_digest) REFERENCES gc_authority.registries(id,version,digest),CHECK(scope_tenant_id=tenant_id),CHECK(created_by=issuer_identity_id),CHECK(beneficiary_kind='human' OR kind IN('ordinary-role','responsibility')),CHECK((scope_kind='tenant' AND num_nonnulls(domain_id,include_descendants,resource_kind,resource_id)=0) OR (scope_kind='domain' AND domain_id IS NOT NULL AND include_descendants IS NOT NULL AND resource_kind IS NULL AND resource_id IS NULL) OR (scope_kind='resource' AND domain_id IS NULL AND include_descendants IS NULL AND resource_kind=ANY(gc_authority.resource_kinds()) AND gc_authority.valid_uuid(resource_id))),CHECK((not_before IS NULL OR gc_authority.valid_time(not_before)) AND (expires_at IS NULL OR gc_authority.valid_time(expires_at)) AND (not_before IS NULL OR expires_at IS NULL OR not_before<expires_at)));
CREATE INDEX authority_grant_beneficiary ON gc_authority.grant_heads(tenant_id,beneficiary_kind,beneficiary_id) WHERE state='active';
CREATE TABLE gc_authority.grant_human_beneficiaries(tenant_id uuid NOT NULL,grant_id uuid NOT NULL,grant_version integer NOT NULL CHECK(grant_version=1),identity_id uuid NOT NULL REFERENCES gc_authority.identity_heads,PRIMARY KEY(tenant_id,grant_id,grant_version),FOREIGN KEY(tenant_id,grant_id,grant_version) REFERENCES gc_authority.grant_heads DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE gc_authority.grant_group_beneficiaries(tenant_id uuid NOT NULL,grant_id uuid NOT NULL,grant_version integer NOT NULL CHECK(grant_version=1),group_id uuid NOT NULL,group_kind text NOT NULL DEFAULT 'group' CHECK(group_kind='group'),PRIMARY KEY(tenant_id,grant_id,grant_version),FOREIGN KEY(tenant_id,grant_id,grant_version) REFERENCES gc_authority.grant_heads DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(tenant_id,group_kind,group_id) REFERENCES gc_authority.definition_heads);
CREATE TABLE gc_authority.ordinary_role_origins(tenant_id uuid NOT NULL,grant_id uuid NOT NULL,grant_version integer NOT NULL CHECK(grant_version=1),role_id uuid NOT NULL,role_version integer NOT NULL,role_kind text NOT NULL DEFAULT 'role' CHECK(role_kind='role'),PRIMARY KEY(tenant_id,grant_id,grant_version),FOREIGN KEY(tenant_id,grant_id,grant_version) REFERENCES gc_authority.grant_heads DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(tenant_id,role_kind,role_id,role_version) REFERENCES gc_authority.definition_versions);
CREATE TABLE gc_authority.responsibility_origins(tenant_id uuid NOT NULL,grant_id uuid NOT NULL,grant_version integer NOT NULL CHECK(grant_version=1),assignment_id uuid NOT NULL CHECK(gc_authority.valid_uuid(assignment_id)),assignment_version integer NOT NULL CHECK(assignment_version=1),type_id uuid NOT NULL,type_version integer NOT NULL,type_kind text NOT NULL DEFAULT 'responsibility-type' CHECK(type_kind='responsibility-type'),mapped_role_id uuid,mapped_role_version integer,effective_grant_id uuid,PRIMARY KEY(tenant_id,grant_id,grant_version),UNIQUE(tenant_id,assignment_id,assignment_version),FOREIGN KEY(tenant_id,grant_id,grant_version) REFERENCES gc_authority.grant_heads DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(tenant_id,type_kind,type_id,type_version) REFERENCES gc_authority.definition_versions,CHECK((mapped_role_id IS NULL)=(mapped_role_version IS NULL)));
CREATE TABLE gc_authority.connected_parents(tenant_id uuid NOT NULL,child_id uuid NOT NULL,child_version integer NOT NULL CHECK(child_version=1),parent_id uuid NOT NULL,parent_version integer NOT NULL CHECK(parent_version=1),parent_kind text NOT NULL CHECK(parent_kind IN('grant','delegation')),via_group_membership_id uuid,via_group_membership_version integer,PRIMARY KEY(tenant_id,child_id,child_version),FOREIGN KEY(tenant_id,child_id,child_version) REFERENCES gc_authority.grant_heads DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(tenant_id,parent_id,parent_version) REFERENCES gc_authority.grant_heads,FOREIGN KEY(tenant_id,via_group_membership_id,via_group_membership_version) REFERENCES gc_authority.group_memberships,CHECK((via_group_membership_id IS NULL)=(via_group_membership_version IS NULL)),CHECK(child_id<>parent_id));
CREATE TABLE gc_authority.elevation_uses(tenant_id uuid NOT NULL,id uuid NOT NULL CHECK(gc_authority.valid_uuid(id)),issuance_version integer NOT NULL DEFAULT 1 CHECK(issuance_version=1),elevation_id uuid NOT NULL,elevation_version integer NOT NULL CHECK(elevation_version=1),identity_id uuid NOT NULL REFERENCES gc_authority.identity_heads,protected_session_id uuid NOT NULL REFERENCES gc_authn.sessions,protected_session_version integer NOT NULL CHECK(protected_session_version>0),generation bigint NOT NULL CHECK(generation>0),not_before timestamptz,expires_at timestamptz NOT NULL CHECK(gc_authority.valid_time(expires_at)),created_at timestamptz NOT NULL CHECK(gc_authority.valid_time(created_at)),head_version integer NOT NULL CHECK(head_version>0),state text NOT NULL CHECK(state IN('active','revoked')),changed_at timestamptz NOT NULL CHECK(gc_authority.valid_time(changed_at)),PRIMARY KEY(tenant_id,id,issuance_version),FOREIGN KEY(tenant_id,elevation_id,elevation_version) REFERENCES gc_authority.grant_heads,CHECK((not_before IS NULL OR gc_authority.valid_time(not_before)) AND (not_before IS NULL OR not_before<expires_at)));
CREATE INDEX authority_use_session ON gc_authority.elevation_uses(tenant_id,elevation_id,protected_session_id,protected_session_version,generation,identity_id,not_before,id) WHERE state='active';
CREATE TABLE gc_authority.lifecycle_revisions(tenant_id uuid NOT NULL REFERENCES gc_authority.tenant_heads,family text NOT NULL CHECK(family IN('definition','group-membership','grant','elevation-use')),object_id uuid NOT NULL CHECK(gc_authority.valid_uuid(object_id)),definition_kind text CHECK(definition_kind IN('policy','role','responsibility-type','group')),head_version integer NOT NULL CHECK(head_version>0),previous_head_version integer,state text NOT NULL CHECK(state IN('active','retired','revoked')),definition_version integer,changed_at timestamptz NOT NULL CHECK(gc_authority.valid_time(changed_at)),changed_by uuid NOT NULL REFERENCES gc_authority.identity_heads,reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 4000 AND reason !~ '[[:cntrl:]]'),body_digest text NOT NULL CHECK(body_digest ~ '^[0-9a-f]{64}$'),PRIMARY KEY(tenant_id,family,object_id,head_version),CHECK((head_version=1 AND previous_head_version IS NULL) OR previous_head_version=head_version-1),CHECK((family='definition')=(definition_kind IS NOT NULL)),CHECK((family='definition')=(definition_version IS NOT NULL)));
CREATE TABLE gc_authority.projection_measures(id uuid PRIMARY KEY CHECK(gc_authority.valid_uuid(id)),tenant_id uuid NOT NULL REFERENCES gc_authority.tenant_heads,family text NOT NULL CHECK(family IN('definition','policy','deny-intent','group','group-membership','grant','elevation-use')),projection_form text NOT NULL CHECK(projection_form IN('dto','grant-base','elevation-use-embedded')),object_id uuid NOT NULL CHECK(gc_authority.valid_uuid(object_id)),definition_kind text CHECK(definition_kind IN('policy','role','responsibility-type','group')),issuance_or_definition_version integer NOT NULL CHECK(issuance_or_definition_version>0),head_version integer NOT NULL CHECK(head_version>0),sub_id uuid,canonical_bytes bigint NOT NULL CHECK(canonical_bytes BETWEEN 1 AND 8388608),raw_bytes bigint NOT NULL CHECK(raw_bytes BETWEEN 0 AND 8388608),json_nodes bigint NOT NULL CHECK(json_nodes BETWEEN 1 AND 262144),json_depth integer NOT NULL CHECK(json_depth BETWEEN 1 AND 32),projection_hash text NOT NULL CHECK(projection_hash ~ '^[0-9a-f]{64}$'),UNIQUE NULLS NOT DISTINCT(tenant_id,family,projection_form,object_id,definition_kind,issuance_or_definition_version,head_version,sub_id));
CREATE TABLE gc_authority.write_bindings(transaction_id xid8 PRIMARY KEY,backend_pid integer NOT NULL,owner_role_oid oid NOT NULL,tenant_id uuid NOT NULL REFERENCES gc_authority.tenant_heads,started_at timestamptz NOT NULL,deadline_at timestamptz NOT NULL,epoch_before bigint NOT NULL CHECK(epoch_before>0),epoch_after bigint NOT NULL CHECK(epoch_after=epoch_before+1),CHECK(deadline_at=started_at+interval '30 seconds'));
-- Referenced definition UUIDs are unique across kinds; deferred checks additionally
-- prove the literal role discriminator for nullable associations.
ALTER TABLE gc_authority.definition_versions ADD UNIQUE(tenant_id,id,version);
ALTER TABLE gc_authority.responsibility_role_pins ADD FOREIGN KEY(tenant_id,role_id,role_version) REFERENCES gc_authority.definition_versions(tenant_id,id,version);
ALTER TABLE gc_authority.responsibility_origins ADD FOREIGN KEY(tenant_id,mapped_role_id,mapped_role_version) REFERENCES gc_authority.definition_versions(tenant_id,id,version);
CREATE FUNCTION gc_authority.scope(g gc_authority.grant_heads) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT CASE g.scope_kind WHEN 'tenant' THEN jsonb_build_object('kind','tenant','tenantId',g.tenant_id) WHEN 'domain' THEN jsonb_build_object('kind','domain','tenantId',g.tenant_id,'domainId',g.domain_id,'includeDescendants',g.include_descendants) ELSE jsonb_build_object('kind','resource','resource',jsonb_build_object('tenantId',g.tenant_id,'kind',g.resource_kind,'id',g.resource_id)) END $$;
CREATE FUNCTION gc_authority.validity(n timestamptz,e timestamptz) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT jsonb_build_object('notBefore',gc_authority.utc(n),'expiresAt',gc_authority.utc(e)) $$;
CREATE FUNCTION gc_authority.grant_ref(g gc_authority.grant_heads) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT jsonb_build_object('kind',CASE WHEN g.kind IN('delegation','elevation') THEN g.kind ELSE 'grant' END,'id',g.id,'version',g.issuance_version) $$;
CREATE FUNCTION gc_authority.projection_v1(p_tenant uuid,p_family text,p_id uuid,p_version integer,p_head integer,p_sub uuid,p_form text) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$
DECLARE h gc_authority.definition_heads;d gc_authority.definition_versions;p gc_authority.policy_versions;g gc_authority.grant_heads;m gc_authority.group_memberships;u gc_authority.elevation_uses;o gc_authority.ordinary_role_origins;r gc_authority.responsibility_origins;c gc_authority.connected_parents;par gc_authority.grant_heads;rp gc_authority.responsibility_role_pins;di gc_authority.policy_deny_intents;v jsonb;content jsonb;items jsonb;
BEGIN
 PERFORM gc_authority.owner_check();PERFORM gc_authority.require(p_tenant=public.gc_tenant(),'42501');
 IF p_family IN('definition','policy','group','deny-intent') THEN
 SELECT * INTO h FROM gc_authority.definition_heads WHERE tenant_id=p_tenant AND id=p_id;PERFORM gc_authority.require(h.id IS NOT NULL AND h.head_version=p_head AND p_form='dto','23514');
 SELECT * INTO d FROM gc_authority.definition_versions WHERE tenant_id=p_tenant AND id=p_id AND version=p_version;PERFORM gc_authority.require(d.id IS NOT NULL,'23514');
 IF p_family='group' THEN PERFORM gc_authority.require(h.kind='group' AND p_version=h.definition_version AND p_sub IS NULL,'23514');RETURN jsonb_build_object('id',h.id,'tenantId',p_tenant,'revision',h.head_version::text,'state',h.state);END IF;
 IF p_family='deny-intent' THEN SELECT * INTO di FROM gc_authority.policy_deny_intents WHERE tenant_id=p_tenant AND policy_id=p_id AND policy_version=p_version AND rule_id=p_sub;PERFORM gc_authority.require(di.rule_id IS NOT NULL AND h.kind='policy','23514');RETURN jsonb_build_object('ruleId',di.rule_id,'registryVersion',di.registry_version,'registryDigest',di.registry_digest,'resourceKinds',to_jsonb(di.resource_kinds),'expandedActions',to_jsonb(di.expanded_actions));END IF;
 PERFORM gc_authority.require(p_sub IS NULL,'23514');
 IF p_family='policy' THEN SELECT * INTO p FROM gc_authority.policy_versions WHERE tenant_id=p_tenant AND policy_id=p_id AND version=p_version;PERFORM gc_authority.require(p.policy_id IS NOT NULL AND h.kind='policy','23514');SELECT coalesce(jsonb_agg(jsonb_build_object('ruleId',rule_id,'registryVersion',registry_version,'registryDigest',registry_digest,'resourceKinds',to_jsonb(resource_kinds),'expandedActions',to_jsonb(expanded_actions)) ORDER BY rule_id),'[]') INTO items FROM gc_authority.policy_deny_intents WHERE tenant_id=p_tenant AND policy_id=p_id AND policy_version=p_version;RETURN jsonb_build_object('tenantId',p_tenant,'currentHeadVersion',h.definition_version,'state',h.state,'pin',jsonb_build_object('policyId',p_id,'version',p_version,'hash',p.policy_hash),'document',p.policy_document,'resourceWideIntents',items);END IF;
 PERFORM gc_authority.require(h.kind IN('role','responsibility-type'),'23514');content:=jsonb_build_object('metadata',jsonb_build_object('key',h.key,'label',d.label,'description',d.description));
 IF h.kind='role' THEN SELECT coalesce(jsonb_agg(jsonb_build_object('policyId',policy_id,'version',policy_version,'hash',policy_hash) ORDER BY ordinal),'[]') INTO items FROM gc_authority.role_policy_pins WHERE tenant_id=p_tenant AND role_id=p_id AND role_version=p_version;content:=content||jsonb_build_object('policies',items);
 ELSE SELECT * INTO rp FROM gc_authority.responsibility_role_pins WHERE tenant_id=p_tenant AND type_id=p_id AND type_version=p_version;PERFORM gc_authority.require(rp.type_id IS NOT NULL,'23514');content:=content||jsonb_build_object('grantsRole',CASE WHEN rp.role_id IS NULL THEN NULL ELSE jsonb_build_object('roleId',rp.role_id,'version',rp.role_version) END);END IF;
 RETURN jsonb_build_object('formatVersion',1,'kind',h.kind,'id',p_id,'version',p_version,'tenantId',p_tenant,'currentHeadVersion',h.definition_version,'state',h.state,'hash',d.semantic_hash,'content',content);
 ELSIF p_family='group-membership' THEN SELECT * INTO m FROM gc_authority.group_memberships WHERE tenant_id=p_tenant AND id=p_id AND issuance_version=p_version;PERFORM gc_authority.require(m.id IS NOT NULL AND m.head_version=p_head AND p_form='dto' AND p_sub IS NULL,'23514');RETURN jsonb_build_object('ref',jsonb_build_object('id',m.id,'version',m.issuance_version),'tenantId',p_tenant,'groupId',m.group_id,'identityId',m.identity_id,'state',m.state,'validity',gc_authority.validity(m.not_before,m.expires_at));
 ELSIF p_family='elevation-use' THEN SELECT * INTO u FROM gc_authority.elevation_uses WHERE tenant_id=p_tenant AND id=p_id AND issuance_version=p_version;PERFORM gc_authority.require(u.id IS NOT NULL AND u.head_version=p_head AND p_form IN('dto','elevation-use-embedded') AND p_sub IS NULL,'23514');v:=jsonb_build_object('identityId',u.identity_id,'sessionId',u.protected_session_id,'sessionVersion',u.protected_session_version,'generation',u.generation::text,'state',u.state,'validity',gc_authority.validity(u.not_before,u.expires_at));IF p_form='elevation-use-embedded' THEN RETURN v||jsonb_build_object('id',u.id,'version',u.issuance_version);END IF;RETURN v||jsonb_build_object('ref',jsonb_build_object('id',u.id,'version',u.issuance_version),'elevation',jsonb_build_object('kind','elevation','id',u.elevation_id,'version',u.elevation_version));
 ELSIF p_family='grant' THEN SELECT * INTO g FROM gc_authority.grant_heads WHERE tenant_id=p_tenant AND id=p_id AND issuance_version=p_version;PERFORM gc_authority.require(g.id IS NOT NULL AND g.head_version=p_head AND p_sub IS NULL AND p_form=CASE g.kind WHEN 'elevation' THEN 'grant-base' ELSE 'dto' END,'23514');
 v:=jsonb_build_object('ref',gc_authority.grant_ref(g),'tenantId',p_tenant,'state',g.state,'issuer',jsonb_build_object('kind','human','id',g.issuer_identity_id),'scope',gc_authority.scope(g),'validity',gc_authority.validity(g.not_before,g.expires_at),'ceiling',g.effect_ceiling,'kind',g.kind,'beneficiary',jsonb_build_object('kind',g.beneficiary_kind,'id',g.beneficiary_id));
 IF g.kind='ordinary-role' THEN SELECT * INTO o FROM gc_authority.ordinary_role_origins WHERE tenant_id=p_tenant AND grant_id=p_id;PERFORM gc_authority.require(o.grant_id IS NOT NULL,'23514');v:=v||jsonb_build_object('role',jsonb_build_object('roleId',o.role_id,'version',o.role_version),'delegable',g.delegable_ceiling);
 ELSIF g.kind='responsibility' THEN SELECT * INTO r FROM gc_authority.responsibility_origins WHERE tenant_id=p_tenant AND grant_id=p_id;PERFORM gc_authority.require(r.grant_id IS NOT NULL,'23514');v:=v||jsonb_build_object('type',jsonb_build_object('id',r.type_id,'version',r.type_version),'mappedRole',CASE WHEN r.mapped_role_id IS NULL THEN NULL ELSE jsonb_build_object('roleId',r.mapped_role_id,'version',r.mapped_role_version) END,'assignmentId',r.assignment_id,'assignmentVersion',r.assignment_version,'effectiveGrantId',r.effective_grant_id,'delegable',g.delegable_ceiling);
 ELSE SELECT * INTO c FROM gc_authority.connected_parents WHERE tenant_id=p_tenant AND child_id=p_id;SELECT * INTO par FROM gc_authority.grant_heads WHERE tenant_id=p_tenant AND id=c.parent_id;PERFORM gc_authority.require(par.id IS NOT NULL,'23514');v:=v||jsonb_build_object('parent',gc_authority.grant_ref(par));IF g.kind='delegation' THEN v:=v||jsonb_build_object('delegable',g.delegable_ceiling);END IF;END IF;RETURN v;
 END IF;PERFORM gc_authority.require(false,'23514');RETURN NULL;
END $$;
CREATE FUNCTION gc_authority.scalar(v text,kind text) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ BEGIN IF v IS NULL THEN RETURN 'N;';END IF;CASE kind WHEN 'S' THEN RETURN 'S'||octet_length(v)::text||':'||v;WHEN 'U' THEN RETURN 'U'||v::uuid::text||';';WHEN 'I' THEN RETURN 'I'||v::bigint::text||';';ELSE PERFORM gc_authority.require(false);RETURN NULL;END CASE;END $$;
CREATE FUNCTION gc_authority.field(k text,v text,kind text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT gc_authority.scalar(k,'S')||gc_authority.scalar(v,kind) $$;
CREATE FUNCTION gc_authority.install_encoding(op text,request_id uuid,release_ref text,operator_ref text,expected_db_oid oid,expected_owner_oid oid) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 'gc-authority-foundation/v1;'||gc_authority.scalar(op,'S')||gc_authority.field('request_id',request_id::text,'U')||gc_authority.field('release_ref',release_ref,'S')||gc_authority.field('operator_ref',operator_ref,'S')||gc_authority.field('expected_db_oid',expected_db_oid::text,'I')||gc_authority.field('expected_owner_oid',expected_owner_oid::text,'I') $$;
CREATE FUNCTION gc_authority.install_check(req uuid,release_ref text,operator_ref text,db oid,owner_oid oid) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp AS $$ BEGIN
 PERFORM gc_authority.owner_check();PERFORM gc_authority.require(current_setting('transaction_read_only')='off' AND current_setting('transaction_isolation')='read committed' AND gc_authority.valid_uuid(req) AND length(release_ref) BETWEEN 1 AND 256 AND release_ref !~ '[[:cntrl:]]' AND length(operator_ref) BETWEEN 1 AND 256 AND operator_ref !~ '[[:cntrl:]]' AND db=(SELECT oid FROM pg_database WHERE datname=current_database()) AND owner_oid=session_user::regrole::oid);PERFORM gc_authority.tick();END $$;
CREATE FUNCTION gc_authority.receipt(r gc_authority.installation_receipts) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT jsonb_build_object('formatVersion',1,'receiptId',r.id,'operation',r.operation,'targetId',r.target_id,'manifestHash',r.manifest_hash,'recordedAt',gc_authority.utc(r.recorded_at)) $$;
CREATE FUNCTION gc_authority.install_registry_v1(request_id uuid,release_ref text,operator_ref text,expected_db_oid oid,expected_owner_oid oid,registry_id uuid,registry_version integer,registry_document text,expected_digest text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$
DECLARE r gc_authority.installation_receipts;j jsonb;enc text;stamp timestamptz:=date_trunc('milliseconds',clock_timestamp());m bigint[];
BEGIN
 PERFORM gc_authority.install_check(request_id,release_ref,operator_ref,expected_db_oid,expected_owner_oid);PERFORM gc_authority.require(gc_authority.valid_uuid(registry_id) AND registry_version>0 AND expected_digest ~ '^[0-9a-f]{64}$');j:=gc_authority.registry(registry_document);PERFORM gc_authority.require((j->>'version')::int=registry_version AND j->>'digest'=expected_digest);
 enc:=gc_authority.install_encoding('registry-install',request_id,release_ref,operator_ref,expected_db_oid,expected_owner_oid)||gc_authority.field('registry_id',registry_id::text,'U')||gc_authority.field('registry_version',registry_version::text,'I')||gc_authority.field('registry_document',registry_document,'S')||gc_authority.field('expected_digest',expected_digest,'S');
 PERFORM pg_advisory_xact_lock(hashtextextended('gc-authority-install:'||request_id,0));SELECT * INTO r FROM gc_authority.installation_receipts x WHERE x.request_id=install_registry_v1.request_id;IF FOUND THEN PERFORM gc_authority.require(r.manifest_encoding=convert_to(enc,'UTF8'),'40001');RETURN gc_authority.receipt(r);END IF;
 INSERT INTO gc_authority.installation_receipts VALUES(gen_random_uuid(),request_id,'registry-install',registry_id,convert_to(enc,'UTF8'),encode(sha256(convert_to(enc,'UTF8')),'hex'),stamp,expected_db_oid,expected_owner_oid,release_ref,operator_ref) RETURNING * INTO r;
 m:=gc_authority.json_measure(j);INSERT INTO gc_authority.registries VALUES(registry_id,registry_version,expected_digest,registry_document,octet_length(gc_authority.canonical(j)),m[1],r.id,stamp);PERFORM gc_authority.tick();RETURN gc_authority.receipt(r);
END $$;
CREATE FUNCTION gc_authority.initialize_tenant_v1(request_id uuid,release_ref text,operator_ref text,expected_db_oid oid,expected_owner_oid oid,tenant_id uuid,generation bigint,expected_authn_fence_epoch integer,registry_id uuid,registry_version integer,registry_digest text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$
DECLARE r gc_authority.installation_receipts;enc text;stamp timestamptz:=date_trunc('milliseconds',clock_timestamp());old_t text:=current_setting('gc.tenant_id',true);
BEGIN
 PERFORM gc_authority.install_check(request_id,release_ref,operator_ref,expected_db_oid,expected_owner_oid);PERFORM gc_authority.require(gc_authority.valid_uuid(tenant_id) AND gc_authority.valid_uuid(registry_id) AND generation>0 AND expected_authn_fence_epoch>0 AND registry_version>0 AND registry_digest ~ '^[0-9a-f]{64}$');
 enc:=gc_authority.install_encoding('tenant-initialize',request_id,release_ref,operator_ref,expected_db_oid,expected_owner_oid)||gc_authority.field('tenant_id',tenant_id::text,'U')||gc_authority.field('generation',generation::text,'I')||gc_authority.field('expected_authn_fence_epoch',expected_authn_fence_epoch::text,'I')||gc_authority.field('registry_id',registry_id::text,'U')||gc_authority.field('registry_version',registry_version::text,'I')||gc_authority.field('registry_digest',registry_digest,'S');
 PERFORM pg_advisory_xact_lock(hashtextextended('gc-authority-install:'||request_id,0));SELECT * INTO r FROM gc_authority.installation_receipts x WHERE x.request_id=initialize_tenant_v1.request_id;IF FOUND THEN PERFORM gc_authority.require(r.manifest_encoding=convert_to(enc,'UTF8'),'40001');RETURN gc_authority.receipt(r);END IF;
 PERFORM set_config('gc.tenant_id',tenant_id::text,true);PERFORM pg_advisory_xact_lock(hashtextextended(tenant_id::text,0));PERFORM 1 FROM gc_authn.tenant_fences f WHERE f.tenant_id=initialize_tenant_v1.tenant_id AND f.mode='inactive' AND f.generation=initialize_tenant_v1.generation AND f.epoch=expected_authn_fence_epoch FOR SHARE;PERFORM gc_authority.require(FOUND,'40001');
 INSERT INTO gc_authority.installation_receipts VALUES(gen_random_uuid(),request_id,'tenant-initialize',tenant_id,convert_to(enc,'UTF8'),encode(sha256(convert_to(enc,'UTF8')),'hex'),stamp,expected_db_oid,expected_owner_oid,release_ref,operator_ref) RETURNING * INTO r;
 INSERT INTO gc_authority.tenant_heads VALUES(tenant_id,generation,1,registry_id,registry_version,registry_digest,r.id,stamp,'inactive');PERFORM gc_authority.tick();PERFORM set_config('gc.tenant_id',coalesce(old_t,''),true);RETURN gc_authority.receipt(r);
EXCEPTION WHEN OTHERS THEN PERFORM set_config('gc.tenant_id',coalesce(old_t,''),true);RAISE;END $$;
-- Source synchronization never takes a tenant ledger after canonical row locks.
-- Independent receipt/target proof: an orphan, forged hash, unrelated target or
-- mismatched typed preimage cannot commit even through direct owner fixture DML.
CREATE FUNCTION gc_authority.installation_complete() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$
DECLARE r gc_authority.installation_receipts;z gc_authority.registries;h gc_authority.tenant_heads;f gc_authn.tenant_fences;j jsonb;m bigint[];enc text;prefix text;suffix text;middle text;epoch integer;old_t text:=current_setting('gc.tenant_id',true);BEGIN
 PERFORM gc_authority.owner_check();PERFORM gc_authority.tick();
 IF TG_TABLE_NAME='installation_receipts' THEN r:=NEW;ELSE SELECT * INTO r FROM gc_authority.installation_receipts WHERE id=CASE TG_TABLE_NAME WHEN 'registries' THEN (to_jsonb(NEW)->>'installed_by')::uuid ELSE (to_jsonb(NEW)->>'initialized_by')::uuid END;END IF;
 PERFORM gc_authority.require(r.id IS NOT NULL AND r.manifest_hash=encode(sha256(r.manifest_encoding),'hex') AND r.database_oid=(SELECT oid FROM pg_database WHERE datname=current_database()) AND r.owner_role_oid=session_user::regrole::oid,'23514');PERFORM gc_authority.install_check(r.request_id,r.release_reference,r.operator_reference,r.database_oid,r.owner_role_oid);
 prefix:=gc_authority.install_encoding(r.operation,r.request_id,r.release_reference,r.operator_reference,r.database_oid,r.owner_role_oid);
 IF r.operation='registry-install' THEN
 SELECT * INTO z FROM gc_authority.registries WHERE installed_by=r.id;PERFORM gc_authority.require(z.id=r.target_id AND z.installed_at=r.recorded_at,'23514');j:=gc_authority.registry(z.registry_document);m:=gc_authority.json_measure(j);PERFORM gc_authority.require((j->>'version')::int=z.version AND j->>'digest'=z.digest AND octet_length(gc_authority.canonical(j))=z.canonical_bytes AND m[1]=z.json_nodes,'23514');
 enc:=prefix||gc_authority.field('registry_id',z.id::text,'U')||gc_authority.field('registry_version',z.version::text,'I')||gc_authority.field('registry_document',z.registry_document,'S')||gc_authority.field('expected_digest',z.digest,'S');
 ELSE
 PERFORM set_config('gc.tenant_id',r.target_id::text,true);SELECT * INTO h FROM gc_authority.tenant_heads WHERE tenant_id=r.target_id AND initialized_by=r.id;SELECT * INTO f FROM gc_authn.tenant_fences WHERE tenant_id=r.target_id;
 PERFORM gc_authority.require(h.tenant_id=r.target_id AND h.initialized_at=r.recorded_at AND h.mode='inactive' AND f.mode='inactive' AND f.generation=h.generation,'23514');
 prefix:=prefix||gc_authority.field('tenant_id',h.tenant_id::text,'U')||gc_authority.field('generation',h.generation::text,'I')||gc_authority.scalar('expected_authn_fence_epoch','S')||'I';suffix:=';'||gc_authority.field('registry_id',h.registry_id::text,'U')||gc_authority.field('registry_version',h.registry_version::text,'I')||gc_authority.field('registry_digest',h.registry_digest,'S');enc:=convert_from(r.manifest_encoding,'UTF8');
 PERFORM gc_authority.require(left(enc,length(prefix))=prefix AND right(enc,length(suffix))=suffix AND length(enc)>length(prefix)+length(suffix),'23514');middle:=substr(enc,length(prefix)+1,length(enc)-length(prefix)-length(suffix));PERFORM gc_authority.require(middle ~ '^[1-9][0-9]{0,9}$','23514');epoch:=middle::integer;PERFORM gc_authority.require(epoch=f.epoch,'23514');enc:=prefix||epoch::text||suffix;
 END IF;
 PERFORM gc_authority.require(r.manifest_encoding=convert_to(enc,'UTF8'),'23514');PERFORM set_config('gc.tenant_id',coalesce(old_t,''),true);RETURN NULL;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('gc.tenant_id',coalesce(old_t,''),true);RAISE;END $$;
CREATE CONSTRAINT TRIGGER authority_installation_receipt_complete AFTER INSERT ON gc_authority.installation_receipts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION gc_authority.installation_complete();
CREATE CONSTRAINT TRIGGER authority_registry_complete AFTER INSERT ON gc_authority.registries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION gc_authority.installation_complete();
CREATE CONSTRAINT TRIGGER authority_tenant_complete AFTER INSERT ON gc_authority.tenant_heads DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION gc_authority.installation_complete();
CREATE FUNCTION gc_authority.identity_sync() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$
DECLARE i uuid;pres boolean;iss text;sub text;act boolean;stamp timestamptz:=date_trunc('milliseconds',clock_timestamp());body jsonb;
BEGIN
 i:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;pres:=TG_OP<>'DELETE';IF pres THEN iss:=NEW.issuer;sub:=NEW.subject;act:=NEW.active;ELSE act:=false;END IF;
 IF TG_OP='UPDATE' THEN PERFORM gc_authority.require(OLD.id=NEW.id,'23514');END IF;
 IF TG_OP='UPDATE' AND (OLD.issuer,OLD.subject,OLD.active) IS NOT DISTINCT FROM (NEW.issuer,NEW.subject,NEW.active) THEN RETURN NEW;END IF;
 body:=jsonb_build_object('identityId',i,'present',pres,'canonicalIssuer',iss,'canonicalSubject',sub,'active',act);
 INSERT INTO gc_authority.identity_heads VALUES(i,1,pres,iss,sub,act,stamp,gc_authority.hash(body)) ON CONFLICT(identity_id) DO UPDATE SET revision=gc_authority.identity_heads.revision+1,present=excluded.present,canonical_issuer=excluded.canonical_issuer,canonical_subject=excluded.canonical_subject,active=excluded.active,changed_at=excluded.changed_at,row_digest=excluded.row_digest;RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;
CREATE FUNCTION gc_authority.member_sync() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$
DECLARE t uuid;i uuid;pres boolean;act boolean;stamp timestamptz:=date_trunc('milliseconds',clock_timestamp());body jsonb;old_t text:=current_setting('gc.tenant_id',true);
BEGIN
 t:=CASE WHEN TG_OP='DELETE' THEN OLD.tenant_id ELSE NEW.tenant_id END;i:=CASE WHEN TG_OP='DELETE' THEN OLD.identity_id ELSE NEW.identity_id END;pres:=TG_OP<>'DELETE';act:=CASE WHEN pres THEN NEW.active ELSE false END;
 IF TG_OP='UPDATE' THEN PERFORM gc_authority.require((OLD.tenant_id,OLD.identity_id) IS NOT DISTINCT FROM (NEW.tenant_id,NEW.identity_id),'23514');IF OLD.active=NEW.active THEN RETURN NEW;END IF;END IF;
 body:=jsonb_build_object('tenantId',t,'identityId',i,'present',pres,'active',act);PERFORM set_config('gc.tenant_id',t::text,true);
 INSERT INTO gc_authority.tenant_member_heads VALUES(t,i,gen_random_uuid(),1,pres,act,stamp,gc_authority.hash(body)) ON CONFLICT(tenant_id,identity_id) DO UPDATE SET revision=gc_authority.tenant_member_heads.revision+1,present=excluded.present,active=excluded.active,changed_at=excluded.changed_at,row_digest=excluded.row_digest;PERFORM set_config('gc.tenant_id',coalesce(old_t,''),true);RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('gc.tenant_id',coalesce(old_t,''),true);RAISE;END $$;
LOCK TABLE public.identities,public.memberships IN SHARE ROW EXCLUSIVE MODE;
INSERT INTO gc_authority.identity_heads SELECT id,1,true,issuer,subject,active,date_trunc('milliseconds',clock_timestamp()),gc_authority.hash(jsonb_build_object('identityId',id,'present',true,'canonicalIssuer',issuer,'canonicalSubject',subject,'active',active)) FROM public.identities;
DO $$ DECLARE t uuid;old_t text:=current_setting('gc.tenant_id',true);BEGIN FOR t IN SELECT id FROM public.tenants ORDER BY id LOOP PERFORM set_config('gc.tenant_id',t::text,true);INSERT INTO gc_authority.tenant_member_heads SELECT tenant_id,identity_id,gen_random_uuid(),1,true,active,date_trunc('milliseconds',clock_timestamp()),gc_authority.hash(jsonb_build_object('tenantId',tenant_id,'identityId',identity_id,'present',true,'active',active)) FROM public.memberships WHERE tenant_id=t;END LOOP;PERFORM set_config('gc.tenant_id',coalesce(old_t,''),true);END $$;
CREATE TRIGGER authority_identity_revision AFTER INSERT OR UPDATE OR DELETE ON public.identities FOR EACH ROW EXECUTE FUNCTION gc_authority.identity_sync();
CREATE TRIGGER authority_member_revision AFTER INSERT OR UPDATE OR DELETE ON public.memberships FOR EACH ROW EXECUTE FUNCTION gc_authority.member_sync();
-- New owner-only bridge; no existing SQL012 body or executor grant is changed.
CREATE TYPE gc_authn.foundation_session AS(format_version integer,session_id uuid,session_version integer,identity_id uuid,tenant_id uuid,generation bigint,authn_fence_epoch bigint,issuing_registration_id uuid,issuer_registration_id uuid,identity_binding_id uuid,authenticated_at timestamptz,issued_at timestamptz,expires_at timestamptz);
CREATE FUNCTION gc_authn.foundation_session_v1(session_hash text) RETURNS gc_authn.foundation_session LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,gc_authn,pg_temp SET row_security=on AS $$
DECLARE s gc_authn.sessions;p gc_authn.session_provenance;r gc_authn.executor_registrations;i gc_authn.issuer_registrations;b gc_authn.identity_bindings;f gc_authn.tenant_fences;old_a text:=current_setting('gc.actor_id',true);old_t text:=current_setting('gc.tenant_id',true);
BEGIN
 IF NOT EXISTS(SELECT 1 FROM gc_authn.installation_root z WHERE z.owner_role_oid=session_user::regrole::oid AND z.owner_role_name=session_user AND z.database_oid=(SELECT oid FROM pg_database WHERE datname=current_database())) OR current_setting('role')<>'none' THEN RAISE EXCEPTION 'AUTHORITY_FOUNDATION_EXECUTOR_REJECTED' USING ERRCODE='42501';END IF;
 IF current_setting('transaction_isolation')<>'repeatable read' OR current_setting('transaction_read_only')<>'on' OR session_hash IS NULL OR session_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'AUTHORITY_FOUNDATION_SESSION_REJECTED' USING ERRCODE='28000';END IF;
 IF clock_timestamp()>=transaction_timestamp()+interval '30 seconds' THEN RAISE EXCEPTION 'AUTHORITY_FOUNDATION_DEADLINE' USING ERRCODE='57014';END IF;
 SELECT * INTO s FROM gc_authn.sessions x WHERE x.session_hash=foundation_session_v1.session_hash;PERFORM gc_authn.require_auth(s.id IS NOT NULL AND s.revoked_at IS NULL AND s.expires_at>clock_timestamp());PERFORM gc_authn.validate_session(s.id);
 SELECT * INTO p FROM gc_authn.session_provenance WHERE session_id=s.id;r:=gc_authn.current_registration(p.issuing_executor_registration_id,'login');i:=gc_authn.live_issuer(r.id);SELECT * INTO b FROM gc_authn.identity_bindings WHERE id=p.identity_binding_id;
 PERFORM gc_authn.require_auth((r.generation,i.id,b.issuer_registration_id,b.identity_id) IS NOT DISTINCT FROM (s.generation,p.issuer_registration_id,i.id,s.identity_id) AND b.revoked_at IS NULL AND b.expires_at>clock_timestamp());
 PERFORM set_config('gc.actor_id',s.identity_id::text,true);PERFORM set_config('gc.tenant_id',s.selected_tenant_id::text,true);
 PERFORM gc_authn.require_auth(EXISTS(SELECT 1 FROM public.identities x WHERE x.id=s.identity_id AND x.issuer=b.canonical_issuer AND x.subject=b.subject AND x.active) AND EXISTS(SELECT 1 FROM public.memberships m WHERE m.tenant_id=s.selected_tenant_id AND m.identity_id=s.identity_id AND m.active));
 SELECT * INTO f FROM gc_authn.tenant_fences WHERE tenant_id=s.selected_tenant_id;PERFORM gc_authn.require_auth(f.tenant_id IS NOT NULL AND f.generation=s.generation AND f.mode='inactive');
 PERFORM set_config('gc.actor_id',coalesce(old_a,''),true);PERFORM set_config('gc.tenant_id',coalesce(old_t,''),true);
 IF clock_timestamp()>=transaction_timestamp()+interval '30 seconds' THEN RAISE EXCEPTION 'AUTHORITY_FOUNDATION_DEADLINE' USING ERRCODE='57014';END IF;PERFORM gc_authn.require_auth(least(s.expires_at,r.expires_at,i.expires_at,b.expires_at)>clock_timestamp());
 RETURN(1,s.id,s.version,s.identity_id,s.selected_tenant_id,s.generation::bigint,f.epoch::bigint,r.id,i.id,b.id,s.authenticated_at,s.issued_at,s.expires_at)::gc_authn.foundation_session;
EXCEPTION WHEN SQLSTATE '28000' OR SQLSTATE '23514' THEN PERFORM set_config('gc.actor_id',coalesce(old_a,''),true);PERFORM set_config('gc.tenant_id',coalesce(old_t,''),true);RAISE EXCEPTION 'AUTHORITY_FOUNDATION_SESSION_REJECTED' USING ERRCODE='28000';WHEN OTHERS THEN PERFORM set_config('gc.actor_id',coalesce(old_a,''),true);PERFORM set_config('gc.tenant_id',coalesce(old_t,''),true);RAISE;END $$;
GRANT CREATE ON SCHEMA gc_authn TO gc_authn_definer;
REVOKE ALL ON TYPE gc_authn.foundation_session FROM PUBLIC;
REVOKE ALL ON FUNCTION gc_authn.foundation_session_v1(text) FROM PUBLIC;
ALTER TYPE gc_authn.foundation_session OWNER TO gc_authn_definer;
ALTER FUNCTION gc_authn.foundation_session_v1(text) OWNER TO gc_authn_definer;
GRANT SELECT ON gc_authn.installation_root TO gc_authn_definer;
SET LOCAL ROLE gc_authn_definer;
-- Creation defaults follow the actual creator, never an inherited role. Cover
-- the protected definer too without regranting CREATE or touching old ACLs.
ALTER DEFAULT PRIVILEGES REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
ALTER DEFAULT PRIVILEGES REVOKE USAGE ON TYPES FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA gc_authn REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA gc_authn REVOKE USAGE ON TYPES FROM PUBLIC;
DO $$ BEGIN EXECUTE format('GRANT USAGE ON TYPE gc_authn.foundation_session TO %I',session_user);EXECUTE format('GRANT EXECUTE ON FUNCTION gc_authn.foundation_session_v1(text) TO %I',session_user);END $$;
RESET ROLE;
REVOKE CREATE ON SCHEMA gc_authn FROM gc_authn_definer;
CREATE FUNCTION gc_authority.immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION 'AUTHORITY_FOUNDATION_INTEGRITY' USING ERRCODE='23514';END $$;
CREATE FUNCTION gc_authority.binding() RETURNS gc_authority.write_bindings LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE b gc_authority.write_bindings;BEGIN PERFORM gc_authority.owner_check();PERFORM gc_authority.tick();SELECT * INTO b FROM gc_authority.write_bindings WHERE transaction_id=pg_current_xact_id();PERFORM gc_authority.require(b.transaction_id IS NOT NULL AND b.backend_pid=pg_backend_pid() AND b.owner_role_oid=session_user::regrole::oid AND b.tenant_id=public.gc_tenant() AND b.started_at=transaction_timestamp() AND b.deadline_at>clock_timestamp(),'42501');RETURN b;END $$;
CREATE FUNCTION gc_authority.foundation_write_begin_v1(tenant_id uuid,expected_epoch bigint) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE h gc_authority.tenant_heads;b gc_authority.write_bindings;BEGIN
 PERFORM gc_authority.owner_check();PERFORM gc_authority.tick();PERFORM gc_authority.require(current_setting('transaction_read_only')='off' AND current_setting('transaction_isolation')='read committed' AND gc_authority.valid_uuid(tenant_id) AND expected_epoch>0);PERFORM gc_authority.require(NOT EXISTS(SELECT 1 FROM gc_authority.write_bindings WHERE transaction_id=pg_current_xact_id()),'23514');
 PERFORM set_config('gc.tenant_id',tenant_id::text,true);PERFORM set_config('lock_timeout',greatest(1,least(2000,floor(extract(epoch FROM transaction_timestamp()+interval '30 seconds'-clock_timestamp())*1000)))::text||'ms',true);
 PERFORM pg_advisory_xact_lock(hashtextextended(tenant_id::text,0));SELECT * INTO h FROM gc_authority.tenant_heads x WHERE x.tenant_id=foundation_write_begin_v1.tenant_id FOR UPDATE;PERFORM gc_authority.require(h.tenant_id IS NOT NULL AND h.authority_epoch=expected_epoch AND h.authority_epoch<9223372036854775807,'40001');
 INSERT INTO gc_authority.write_bindings VALUES(pg_current_xact_id(),pg_backend_pid(),session_user::regrole::oid,tenant_id,transaction_timestamp(),transaction_timestamp()+interval '30 seconds',expected_epoch,expected_epoch+1) RETURNING * INTO b;
 UPDATE gc_authority.tenant_heads x SET authority_epoch=b.epoch_after WHERE x.tenant_id=b.tenant_id;PERFORM gc_authority.tick();RETURN jsonb_build_object('formatVersion',1,'tenantId',tenant_id,'epochBefore',b.epoch_before::text,'epochAfter',b.epoch_after::text);
END $$;
CREATE FUNCTION gc_authority.write_statement() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ BEGIN PERFORM gc_authority.binding();RETURN NULL;END $$;
CREATE FUNCTION gc_authority.write_row() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE b gc_authority.write_bindings;n jsonb:=to_jsonb(NEW);o jsonb:=to_jsonb(OLD);fields text[];BEGIN
 b:=gc_authority.binding();PERFORM gc_authority.require(TG_OP<>'DELETE' AND (n->>'tenant_id')::uuid=b.tenant_id,'23514');
 IF TG_OP='UPDATE' THEN
  PERFORM gc_authority.require(TG_TABLE_NAME IN('definition_heads','group_memberships','grant_heads','elevation_uses'),'23514');fields:=CASE TG_TABLE_NAME WHEN 'definition_heads' THEN ARRAY['head_version','state','changed_at','definition_version'] ELSE ARRAY['head_version','state','changed_at'] END;
  PERFORM gc_authority.require(n-fields=o-fields AND (o->>'head_version')::int<2147483647 AND (n->>'head_version')::int=(o->>'head_version')::int+1 AND (n->>'changed_at')::timestamptz>=(o->>'changed_at')::timestamptz AND o->>'state'='active','23514');
  IF TG_TABLE_NAME='definition_heads' THEN PERFORM gc_authority.require((n->>'state'='retired' AND n->>'definition_version'=o->>'definition_version') OR (n->>'state'='active' AND (n->>'definition_version')::bigint=(o->>'definition_version')::bigint+1),'23514');ELSE PERFORM gc_authority.require(n->>'state'='revoked','23514');END IF;
 ELSE IF TG_TABLE_NAME IN('definition_heads','group_memberships','grant_heads','elevation_uses') THEN PERFORM gc_authority.require(n->>'head_version'='1' AND n->>'state'='active' AND (TG_TABLE_NAME<>'definition_heads' OR n->>'definition_version'='1'),'23514');END IF;END IF;
 RETURN NEW;END $$;
CREATE FUNCTION gc_authority.epoch_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE b gc_authority.write_bindings;BEGIN b:=gc_authority.binding();PERFORM gc_authority.require(TG_OP='UPDATE' AND to_jsonb(NEW)-'authority_epoch'=to_jsonb(OLD)-'authority_epoch' AND NEW.tenant_id=b.tenant_id AND OLD.authority_epoch=b.epoch_before AND NEW.authority_epoch=b.epoch_after,'23514');RETURN NEW;END $$;
CREATE TRIGGER authority_tenant_no_truncate BEFORE TRUNCATE ON gc_authority.tenant_heads FOR EACH STATEMENT EXECUTE FUNCTION gc_authority.immutable();
CREATE TRIGGER authority_epoch_guard BEFORE UPDATE OR DELETE ON gc_authority.tenant_heads FOR EACH ROW EXECUTE FUNCTION gc_authority.epoch_guard();
CREATE FUNCTION gc_authority.temporal_subset(child jsonb,parent jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT (parent->>'notBefore' IS NULL OR (child->>'notBefore' IS NOT NULL AND (child->>'notBefore')::timestamptz>=(parent->>'notBefore')::timestamptz)) AND (parent->>'expiresAt' IS NULL OR (child->>'expiresAt' IS NOT NULL AND (child->>'expiresAt')::timestamptz<=(parent->>'expiresAt')::timestamptz)) $$;
CREATE FUNCTION gc_authority.finite_subset(child jsonb,parent jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT (parent->'actions') @> (child->'actions') AND (NOT parent ? 'resourceKinds' OR NOT child ? 'resourceKinds' OR (parent->'resourceKinds') @> (child->'resourceKinds')) AND (parent->'fields'='null'::jsonb OR (child->'fields'<>'null'::jsonb AND (parent->'fields') @> (child->'fields'))) AND gc_authority.temporal_subset(child->'validity',parent->'validity') $$;
CREATE FUNCTION gc_authority.scope_tenant(v jsonb) RETURNS uuid LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT CASE WHEN v->>'kind'='resource' THEN (v#>>'{resource,tenantId}')::uuid ELSE (v->>'tenantId')::uuid END $$;
CREATE FUNCTION gc_authority.source_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE j jsonb;p jsonb;r jsonb;h gc_authority.definition_heads;v gc_authority.definition_versions;n integer:=0;rule_expr jsonb;stats integer[];BEGIN
 IF TG_TABLE_NAME='policy_versions' THEN SELECT gc_authority.registry(registry_document) INTO r FROM gc_authority.registries z JOIN gc_authority.tenant_heads t ON (t.registry_id,t.registry_version,t.registry_digest)=(z.id,z.version,z.digest) WHERE t.tenant_id=NEW.tenant_id;p:=gc_authority.policy(NEW.policy_document,r->'fields');FOR rule_expr IN SELECT value FROM jsonb_array_elements(p->'rules') LOOP stats:=gc_authority.expression_stats(rule_expr->'when');n:=n+stats[1];END LOOP;
 PERFORM gc_authority.require((p->>'id')::uuid=NEW.policy_id AND (p->>'version')::int=NEW.version AND gc_authority.hash(p)=NEW.policy_hash AND octet_length(gc_authority.canonical(p))=NEW.canonical_bytes AND jsonb_array_length(p->'rules')=NEW.rule_count AND n=NEW.expression_node_count,'23514');
 ELSIF TG_TABLE_NAME='grant_heads' THEN SELECT gc_authority.registry(registry_document) INTO r FROM gc_authority.registries WHERE (id,version,digest)=(NEW.registry_id,NEW.registry_version,NEW.registry_digest);PERFORM gc_authority.require(r IS NOT NULL,'23514');
 PERFORM gc_authority.require(pg_column_size(NEW.effect_ceiling)<=8388608 AND gc_authority.scope(NEW)=gc_authority.normalize(gc_authority.scope(NEW),'"scope"') AND NEW.effect_ceiling=gc_authority.normalize(NEW.effect_ceiling,'"effect"',r->'fields') AND gc_authority.scope_tenant(NEW.effect_ceiling->'scope')=NEW.tenant_id AND gc_authority.temporal_subset(NEW.effect_ceiling->'validity',gc_authority.validity(NEW.not_before,NEW.expires_at)) AND gc_authority.scope_literal_subset(NEW.effect_ceiling->'scope',gc_authority.scope(NEW)),'23514');
 PERFORM gc_authority.require(NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.effect_ceiling->'actions') x WHERE x=ANY(gc_authority.service_actions())),'23514');
 IF NEW.delegable_ceiling IS NOT NULL THEN PERFORM gc_authority.require(NEW.delegable_ceiling=gc_authority.normalize(NEW.delegable_ceiling,'"delegable"',r->'fields') AND gc_authority.scope_tenant(NEW.delegable_ceiling->'scope')=NEW.tenant_id AND gc_authority.finite_subset(NEW.delegable_ceiling,NEW.effect_ceiling) AND gc_authority.scope_literal_subset(NEW.delegable_ceiling->'scope',NEW.effect_ceiling->'scope'),'23514');END IF;
 IF NEW.control_ceiling IS NOT NULL THEN PERFORM gc_authority.require(NEW.control_ceiling=gc_authority.normalize(NEW.control_ceiling,'"control"',r->'fields') AND gc_authority.scope_tenant(NEW.control_ceiling->'scope')=NEW.tenant_id,'23514');END IF;
 PERFORM gc_authority.require((NEW.control_ceiling IS NOT NULL)=EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.effect_ceiling->'actions') x WHERE x=ANY(gc_authority.admin_actions())),'23514');
 IF NEW.kind='elevation' THEN PERFORM gc_authority.require(NEW.expires_at IS NOT NULL AND NEW.delegable_ceiling IS NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.effect_ceiling->'actions') x WHERE NOT x=ANY(gc_authority.compatible_actions())),'23514');ELSIF NEW.kind='delegation' THEN PERFORM gc_authority.require(NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.effect_ceiling->'actions') x WHERE x=ANY(gc_authority.field_actions())),'23514');END IF;
 END IF;RETURN NEW;END $$;
CREATE TRIGGER authority_policy_shape BEFORE INSERT ON gc_authority.policy_versions FOR EACH ROW EXECUTE FUNCTION gc_authority.source_guard();
CREATE TRIGGER authority_grant_shape BEFORE INSERT OR UPDATE ON gc_authority.grant_heads FOR EACH ROW EXECUTE FUNCTION gc_authority.source_guard();
CREATE FUNCTION gc_authority.measure_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE v jsonb;m bigint[];raw bigint:=0;k text;BEGIN
 v:=gc_authority.projection_v1(NEW.tenant_id,NEW.family,NEW.object_id,NEW.issuance_or_definition_version,NEW.head_version,NEW.sub_id,NEW.projection_form);m:=gc_authority.json_measure(v);
 IF NEW.family='policy' THEN SELECT octet_length(policy_document) INTO raw FROM gc_authority.policy_versions WHERE tenant_id=NEW.tenant_id AND policy_id=NEW.object_id AND version=NEW.issuance_or_definition_version;END IF;
 IF NEW.family IN('definition','policy','group','deny-intent') THEN SELECT kind INTO k FROM gc_authority.definition_heads WHERE tenant_id=NEW.tenant_id AND id=NEW.object_id;END IF;
 PERFORM gc_authority.require(NEW.definition_kind IS NOT DISTINCT FROM k AND NEW.canonical_bytes=octet_length(gc_authority.canonical(v)) AND NEW.raw_bytes=raw AND NEW.json_nodes=m[1] AND NEW.json_depth=m[2] AND NEW.projection_hash=gc_authority.hash(v),'23514');RETURN NEW;END $$;
CREATE TRIGGER authority_measure_source BEFORE INSERT ON gc_authority.projection_measures FOR EACH ROW EXECUTE FUNCTION gc_authority.measure_guard();
CREATE FUNCTION gc_authority.no_action_predicate(v jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE x jsonb;BEGIN IF v->>'op'='action-in' THEN RETURN false;END IF;IF v ? 'children' THEN FOR x IN SELECT value FROM jsonb_array_elements(v->'children') LOOP IF NOT gc_authority.no_action_predicate(x) THEN RETURN false;END IF;END LOOP;END IF;RETURN true;END $$;
-- Root-adopted finite lock-plan refinement. Claims are server-derived, immutable,
-- xid/backend/tenant-bound, and cannot be replaced with a caller GUC.
CREATE TABLE gc_authority.write_lock_claims(transaction_id xid8 NOT NULL REFERENCES gc_authority.write_bindings,tenant_id uuid NOT NULL REFERENCES gc_authority.tenant_heads,phase text NOT NULL,kind text NOT NULL,object_id uuid NOT NULL CHECK(gc_authority.valid_uuid(object_id)),PRIMARY KEY(transaction_id,phase,kind,object_id),CHECK((phase='configuration' AND kind IN('login-generation','executor','issuer','binding','authn-tenant')) OR (phase='principal' AND kind IN('identity','member')) OR (phase='session' AND kind='session') OR (phase='sealed' AND kind='tenant')));
CREATE FUNCTION gc_authority.foundation_write_locks_v1(principal_ids uuid[],session_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$
DECLARE b gc_authority.write_bindings;lock_row record;before_refs jsonb;after_refs jsonb;n integer;i uuid;executors uuid[];issuers uuid[];bindings uuid[];
BEGIN
 b:=gc_authority.binding();PERFORM gc_authority.require(principal_ids IS NOT NULL AND session_ids IS NOT NULL AND cardinality(principal_ids)<=2048 AND cardinality(session_ids)<=1024 AND coalesce(array_ndims(principal_ids),1)=1 AND coalesce(array_ndims(session_ids),1)=1 AND array_position(principal_ids,NULL) IS NULL AND array_position(session_ids,NULL) IS NULL AND NOT '00000000-0000-0000-0000-000000000000'::uuid=ANY(principal_ids||session_ids) AND principal_ids=ARRAY(SELECT DISTINCT x FROM unnest(principal_ids)x ORDER BY x) AND session_ids=ARRAY(SELECT DISTINCT x FROM unnest(session_ids)x ORDER BY x));
 PERFORM gc_authority.require(NOT EXISTS(SELECT 1 FROM gc_authority.write_lock_claims WHERE transaction_id=b.transaction_id),'23514');
 SELECT coalesce(jsonb_agg(jsonb_build_array(s.id,s.identity_id,s.selected_tenant_id,s.version,s.generation,p.issuing_executor_registration_id,p.issuer_registration_id,p.identity_binding_id) ORDER BY s.id),'[]'),array_agg(DISTINCT p.issuing_executor_registration_id),array_agg(DISTINCT p.issuer_registration_id),array_agg(DISTINCT p.identity_binding_id),count(*) INTO before_refs,executors,issuers,bindings,n FROM gc_authn.sessions s JOIN gc_authn.session_provenance p ON p.session_id=s.id WHERE s.id=ANY(session_ids) AND s.selected_tenant_id=b.tenant_id AND s.identity_id=ANY(principal_ids);
 PERFORM gc_authority.require(n=cardinality(session_ids),'23514');PERFORM gc_authority.tick();
 FOR lock_row IN SELECT kind,channel_id FROM gc_authn.generation_heads WHERE executor_registration_id=ANY(executors) ORDER BY kind,channel_id FOR SHARE LOOP PERFORM gc_authority.require(lock_row.kind='login','23514');INSERT INTO gc_authority.write_lock_claims VALUES(b.transaction_id,b.tenant_id,'configuration','login-generation',lock_row.channel_id);END LOOP;
 FOR lock_row IN SELECT id FROM gc_authn.executor_registrations WHERE id=ANY(executors) ORDER BY id FOR SHARE LOOP INSERT INTO gc_authority.write_lock_claims VALUES(b.transaction_id,b.tenant_id,'configuration','executor',lock_row.id);END LOOP;
 FOR lock_row IN SELECT id FROM gc_authn.issuer_registrations WHERE id=ANY(issuers) ORDER BY id FOR SHARE LOOP INSERT INTO gc_authority.write_lock_claims VALUES(b.transaction_id,b.tenant_id,'configuration','issuer',lock_row.id);END LOOP;
 FOR lock_row IN SELECT id FROM gc_authn.identity_bindings WHERE id=ANY(bindings) ORDER BY id FOR SHARE LOOP INSERT INTO gc_authority.write_lock_claims VALUES(b.transaction_id,b.tenant_id,'configuration','binding',lock_row.id);END LOOP;
 PERFORM 1 FROM gc_authn.tenant_fences f JOIN gc_authority.tenant_heads h USING(tenant_id) WHERE f.tenant_id=b.tenant_id AND f.mode='inactive' AND f.generation=h.generation FOR SHARE OF f;PERFORM gc_authority.require(FOUND,'23514');INSERT INTO gc_authority.write_lock_claims VALUES(b.transaction_id,b.tenant_id,'configuration','authn-tenant',b.tenant_id);
 PERFORM gc_authority.require(NOT EXISTS(SELECT 1 FROM gc_authn.sessions x JOIN gc_authn.session_provenance p ON p.session_id=x.id LEFT JOIN gc_authn.executor_registrations r ON r.id=p.issuing_executor_registration_id LEFT JOIN gc_authn.generation_heads h ON h.executor_registration_id=r.id AND h.kind=r.kind AND h.channel_id=r.channel_id LEFT JOIN gc_authn.issuer_registrations z ON z.id=p.issuer_registration_id LEFT JOIN gc_authn.identity_bindings q ON q.id=p.identity_binding_id WHERE x.id=ANY(session_ids) AND (r.id IS NULL OR h.executor_registration_id IS NULL OR r.kind<>'login' OR r.revoked_at IS NOT NULL OR r.expires_at<=clock_timestamp() OR z.revoked_at IS NOT NULL OR z.expires_at<=clock_timestamp() OR q.revoked_at IS NOT NULL OR q.expires_at<=clock_timestamp() OR x.generation<>r.generation OR q.identity_id<>x.identity_id OR q.issuer_registration_id<>z.id)),'23514');
 -- A single global identity ordering precedes all tenant membership locks.
 PERFORM id FROM public.identities WHERE id=ANY(principal_ids) ORDER BY id FOR SHARE;
 PERFORM identity_id FROM gc_authority.identity_heads WHERE identity_id=ANY(principal_ids) ORDER BY identity_id FOR SHARE;GET DIAGNOSTICS n=ROW_COUNT;PERFORM gc_authority.require(n=cardinality(principal_ids),'23514');
 PERFORM identity_id FROM public.memberships WHERE tenant_id=b.tenant_id AND identity_id=ANY(principal_ids) ORDER BY identity_id FOR SHARE;
 PERFORM identity_id FROM gc_authority.tenant_member_heads WHERE tenant_id=b.tenant_id AND identity_id=ANY(principal_ids) ORDER BY identity_id FOR SHARE;
 FOREACH i IN ARRAY principal_ids LOOP INSERT INTO gc_authority.write_lock_claims VALUES(b.transaction_id,b.tenant_id,'principal','identity',i),(b.transaction_id,b.tenant_id,'principal','member',i);END LOOP;
 FOR lock_row IN SELECT id FROM gc_authn.sessions WHERE id=ANY(session_ids) ORDER BY id FOR SHARE LOOP INSERT INTO gc_authority.write_lock_claims VALUES(b.transaction_id,b.tenant_id,'session','session',lock_row.id);END LOOP;
 SELECT coalesce(jsonb_agg(jsonb_build_array(s.id,s.identity_id,s.selected_tenant_id,s.version,s.generation,p.issuing_executor_registration_id,p.issuer_registration_id,p.identity_binding_id) ORDER BY s.id),'[]') INTO after_refs FROM gc_authn.sessions s JOIN gc_authn.session_provenance p ON p.session_id=s.id WHERE s.id=ANY(session_ids);
 PERFORM gc_authority.require(before_refs=after_refs,'40001');PERFORM gc_authority.tick();INSERT INTO gc_authority.write_lock_claims VALUES(b.transaction_id,b.tenant_id,'sealed','tenant',b.tenant_id);
 RETURN jsonb_build_object('formatVersion',1,'tenantId',b.tenant_id,'principalCount',cardinality(principal_ids),'sessionCount',cardinality(session_ids));
END $$;
CREATE FUNCTION gc_authority.sealed() RETURNS gc_authority.write_bindings LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE b gc_authority.write_bindings;BEGIN b:=gc_authority.binding();PERFORM gc_authority.require(EXISTS(SELECT 1 FROM gc_authority.write_lock_claims c WHERE c.transaction_id=b.transaction_id AND c.tenant_id=b.tenant_id AND c.phase='sealed' AND c.kind='tenant' AND c.object_id=b.tenant_id),'23514');RETURN b;END $$;
CREATE FUNCTION gc_authority.claimed(kind text,id uuid) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE b gc_authority.write_bindings;BEGIN b:=gc_authority.sealed();PERFORM gc_authority.require(EXISTS(SELECT 1 FROM gc_authority.write_lock_claims c WHERE c.transaction_id=b.transaction_id AND c.tenant_id=b.tenant_id AND c.kind=claimed.kind AND c.object_id=claimed.id AND c.phase=CASE claimed.kind WHEN 'session' THEN 'session' ELSE 'principal' END),'23514');END $$;
CREATE FUNCTION gc_authority.write_claim_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE j jsonb:=to_jsonb(NEW);k text;BEGIN
 PERFORM gc_authority.sealed();FOREACH k IN ARRAY ARRAY['created_by','changed_by','issuer_identity_id','identity_id'] LOOP IF j ? k THEN PERFORM gc_authority.claimed('identity',(j->>k)::uuid);END IF;END LOOP;
 IF TG_TABLE_NAME='grant_heads' THEN IF j->>'beneficiary_kind'='human' THEN PERFORM gc_authority.claimed('identity',(j->>'beneficiary_id')::uuid);END IF;END IF;
 IF TG_TABLE_NAME='elevation_uses' THEN PERFORM gc_authority.claimed('session',(j->>'protected_session_id')::uuid);END IF;
 IF TG_TABLE_NAME='connected_parents' THEN FOR k IN SELECT issuer_identity_id::text FROM gc_authority.grant_heads WHERE tenant_id=(j->>'tenant_id')::uuid AND id IN((j->>'child_id')::uuid,(j->>'parent_id')::uuid) UNION SELECT beneficiary_id::text FROM gc_authority.grant_heads WHERE tenant_id=(j->>'tenant_id')::uuid AND id IN((j->>'child_id')::uuid,(j->>'parent_id')::uuid) AND beneficiary_kind='human' UNION SELECT identity_id::text FROM gc_authority.group_memberships WHERE tenant_id=(j->>'tenant_id')::uuid AND id=(j->>'via_group_membership_id')::uuid LOOP PERFORM gc_authority.claimed('identity',k::uuid);END LOOP;END IF;RETURN NEW;END $$;
CREATE FUNCTION gc_authority.lifecycle_insert_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE j jsonb;BEGIN
 CASE NEW.family WHEN 'definition' THEN SELECT to_jsonb(h) INTO j FROM gc_authority.definition_heads h WHERE tenant_id=NEW.tenant_id AND id=NEW.object_id AND kind=NEW.definition_kind;
 WHEN 'grant' THEN SELECT to_jsonb(h) INTO j FROM gc_authority.grant_heads h WHERE tenant_id=NEW.tenant_id AND id=NEW.object_id;
 WHEN 'group-membership' THEN SELECT to_jsonb(h) INTO j FROM gc_authority.group_memberships h WHERE tenant_id=NEW.tenant_id AND id=NEW.object_id;
 WHEN 'elevation-use' THEN SELECT to_jsonb(h) INTO j FROM gc_authority.elevation_uses h WHERE tenant_id=NEW.tenant_id AND id=NEW.object_id;END CASE;
 PERFORM gc_authority.require(CASE NEW.family WHEN 'definition' THEN EXISTS(SELECT 1 FROM gc_authority.definition_heads x WHERE x.tenant_id=NEW.tenant_id AND x.id=NEW.object_id AND x.xmin=pg_current_xact_id()::xid) WHEN 'grant' THEN EXISTS(SELECT 1 FROM gc_authority.grant_heads x WHERE x.tenant_id=NEW.tenant_id AND x.id=NEW.object_id AND x.xmin=pg_current_xact_id()::xid) WHEN 'group-membership' THEN EXISTS(SELECT 1 FROM gc_authority.group_memberships x WHERE x.tenant_id=NEW.tenant_id AND x.id=NEW.object_id AND x.xmin=pg_current_xact_id()::xid) ELSE EXISTS(SELECT 1 FROM gc_authority.elevation_uses x WHERE x.tenant_id=NEW.tenant_id AND x.id=NEW.object_id AND x.xmin=pg_current_xact_id()::xid) END,'23514');
 PERFORM gc_authority.require(j IS NOT NULL AND (j->>'head_version')::int=NEW.head_version AND j->>'state'=NEW.state AND (j->>'changed_at')::timestamptz=NEW.changed_at AND (j->>'definition_version')::int IS NOT DISTINCT FROM NEW.definition_version AND gc_authority.hash(j)=NEW.body_digest,'23514');
 PERFORM gc_authority.require(NEW.head_version=1 OR EXISTS(SELECT 1 FROM gc_authority.lifecycle_revisions r WHERE r.tenant_id=NEW.tenant_id AND r.family=NEW.family AND r.object_id=NEW.object_id AND r.head_version=NEW.head_version-1),'23514');RETURN NEW;END $$;
CREATE TRIGGER authority_lifecycle_source BEFORE INSERT ON gc_authority.lifecycle_revisions FOR EACH ROW EXECUTE FUNCTION gc_authority.lifecycle_insert_guard();
CREATE FUNCTION gc_authority.require_measure(t uuid,f text,i uuid,v integer,h integer,s uuid,form text) RETURNS void LANGUAGE plpgsql STABLE SET search_path=pg_catalog,gc_authority,pg_temp AS $$ BEGIN PERFORM gc_authority.require(EXISTS(SELECT 1 FROM gc_authority.projection_measures m WHERE m.tenant_id=t AND m.family=f AND m.object_id=i AND m.issuance_or_definition_version=v AND m.head_version=h AND m.sub_id IS NOT DISTINCT FROM s AND m.projection_form=form),'23514');END $$;
CREATE FUNCTION gc_authority.validate_definition(t uuid,i uuid) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$
DECLARE h gc_authority.definition_heads;d gc_authority.definition_versions;r gc_authority.responsibility_role_pins;p gc_authority.policy_versions;mark gc_authority.policy_deny_intents;v jsonb;policy jsonb;rule jsonb;reg jsonb;expected text[];n integer;
BEGIN
 PERFORM gc_authority.tick();SELECT * INTO h FROM gc_authority.definition_heads WHERE tenant_id=t AND id=i;PERFORM gc_authority.require(h.id IS NOT NULL,'23514');
 PERFORM gc_authority.require((SELECT count(*)=h.definition_version AND min(version)=1 AND max(version)=h.definition_version FROM gc_authority.definition_versions WHERE tenant_id=t AND id=i),'23514');
 FOR d IN SELECT * FROM gc_authority.definition_versions WHERE tenant_id=t AND id=i ORDER BY version LOOP
 IF h.kind='policy' THEN SELECT * INTO p FROM gc_authority.policy_versions WHERE tenant_id=t AND policy_id=i AND version=d.version;PERFORM gc_authority.require(p.policy_id IS NOT NULL AND p.policy_hash=d.semantic_hash,'23514');PERFORM gc_authority.require_measure(t,'policy',i,d.version,h.head_version,NULL,'dto');
 ELSIF h.kind='group' THEN v:=jsonb_build_object('formatVersion',1,'kind','group','id',i,'version',d.version,'content',jsonb_build_object('metadata',jsonb_build_object('key',h.key,'label',d.label,'description',d.description)));PERFORM gc_authority.require(d.semantic_hash=gc_authority.hash(v),'23514');
 ELSE v:=gc_authority.projection_v1(t,'definition',i,d.version,h.head_version,NULL,'dto');PERFORM gc_authority.require(d.semantic_hash=gc_authority.hash(v-ARRAY['tenantId','currentHeadVersion','state','hash']),'23514');PERFORM gc_authority.require_measure(t,'definition',i,d.version,h.head_version,NULL,'dto');
 IF h.kind='role' THEN PERFORM gc_authority.require((SELECT count(*) BETWEEN 1 AND 32 AND min(ordinal)=0 AND max(ordinal)=count(*)-1 FROM gc_authority.role_policy_pins WHERE tenant_id=t AND role_id=i AND role_version=d.version),'23514');PERFORM gc_authority.require(NOT EXISTS(SELECT 1 FROM (SELECT ordinal,row_number() OVER(ORDER BY policy_id::text||'@'||policy_version::text||'#'||policy_hash COLLATE "C")-1 AS expected FROM gc_authority.role_policy_pins WHERE tenant_id=t AND role_id=i AND role_version=d.version) ordered WHERE ordinal<>ordered.expected),'23514');
 ELSE SELECT * INTO r FROM gc_authority.responsibility_role_pins WHERE tenant_id=t AND type_id=i AND type_version=d.version;PERFORM gc_authority.require(r.type_id IS NOT NULL AND (r.role_id IS NULL OR EXISTS(SELECT 1 FROM gc_authority.definition_versions WHERE tenant_id=t AND kind='role' AND id=r.role_id AND version=r.role_version)),'23514');END IF;END IF;
 END LOOP;
 IF h.kind='group' THEN PERFORM gc_authority.require_measure(t,'group',i,h.definition_version,h.head_version,NULL,'dto');END IF;
 FOR mark IN SELECT * FROM gc_authority.policy_deny_intents WHERE tenant_id=t AND policy_id=i LOOP
 SELECT gc_authority.registry(registry_document) INTO reg FROM gc_authority.registries WHERE (id,version,digest)=(mark.registry_id,mark.registry_version,mark.registry_digest);SELECT gc_authority.policy(policy_document,reg->'fields') INTO policy FROM gc_authority.policy_versions WHERE tenant_id=t AND policy_id=i AND version=mark.policy_version;SELECT value INTO rule FROM jsonb_array_elements(policy->'rules') WHERE value->>'id'=mark.rule_id::text;
 SELECT array_agg(value->>'action' ORDER BY value->>'action' COLLATE "C") INTO expected FROM jsonb_array_elements(reg->'actions') WHERE value->>'family'=CASE WHEN mark.expanded_actions[1]=ANY(gc_authority.service_actions()) THEN 'service' ELSE 'human' END AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(value->'resourceKinds') k WHERE k=ANY(mark.resource_kinds));
 PERFORM gc_authority.require(cardinality(mark.resource_kinds)>0 AND mark.resource_kinds=ARRAY(SELECT DISTINCT k COLLATE "C" FROM unnest(mark.resource_kinds)k ORDER BY k COLLATE "C") AND mark.resource_kinds<@gc_authority.resource_kinds() AND mark.expanded_actions=expected AND rule->>'effect'='deny' AND rule->'fields'='null'::jsonb AND rule->'actions'=to_jsonb(expected) AND gc_authority.no_action_predicate(rule->'when'),'23514');PERFORM gc_authority.require_measure(t,'deny-intent',i,mark.policy_version,h.head_version,mark.rule_id,'dto');END LOOP;
 IF h.state='retired' THEN
  -- Reverse dependency checks retain pinned old versions and future grants.
  PERFORM gc_authority.require(NOT EXISTS(SELECT 1 FROM gc_authority.group_memberships m WHERE m.tenant_id=t AND m.group_id=i AND m.state='active' AND (m.expires_at IS NULL OR m.expires_at>clock_timestamp())),'23514');
  PERFORM gc_authority.require(NOT EXISTS(SELECT 1 FROM gc_authority.grant_heads g LEFT JOIN gc_authority.ordinary_role_origins o ON (o.tenant_id,o.grant_id)=(g.tenant_id,g.id) LEFT JOIN gc_authority.responsibility_origins r_sql ON (r_sql.tenant_id,r_sql.grant_id)=(g.tenant_id,g.id) WHERE g.tenant_id=t AND g.state='active' AND (g.expires_at IS NULL OR g.expires_at>clock_timestamp()) AND (o.role_id=i OR r_sql.type_id=i OR r_sql.mapped_role_id=i OR (g.beneficiary_kind='group' AND g.beneficiary_id=i) OR EXISTS(SELECT 1 FROM gc_authority.role_policy_pins p_sql WHERE p_sql.tenant_id=t AND p_sql.role_id=coalesce(o.role_id,r_sql.mapped_role_id) AND p_sql.role_version=coalesce(o.role_version,r_sql.mapped_role_version) AND p_sql.policy_id=i))),'23514');
  PERFORM gc_authority.require(NOT EXISTS(SELECT 1 FROM gc_authority.grant_heads terminal CROSS JOIN LATERAL gc_authority.root_origin(t,terminal.id) root LEFT JOIN gc_authority.ordinary_role_origins o ON o.tenant_id=t AND o.grant_id=root.id LEFT JOIN gc_authority.responsibility_origins x ON x.tenant_id=t AND x.grant_id=root.id WHERE terminal.tenant_id=t AND terminal.state='active' AND (terminal.expires_at IS NULL OR terminal.expires_at>clock_timestamp()) AND (o.role_id=i OR x.type_id=i OR x.mapped_role_id=i OR EXISTS(SELECT 1 FROM gc_authority.role_policy_pins p_sql WHERE p_sql.tenant_id=t AND p_sql.role_id=coalesce(o.role_id,x.mapped_role_id) AND p_sql.role_version=coalesce(o.role_version,x.mapped_role_version) AND p_sql.policy_id=i))),'23514');
  PERFORM gc_authority.require(NOT EXISTS(SELECT 1 FROM gc_authority.role_policy_pins p_sql JOIN gc_authority.definition_heads rh ON rh.tenant_id=p_sql.tenant_id AND rh.id=p_sql.role_id WHERE p_sql.tenant_id=t AND p_sql.policy_id=i AND rh.state='active') AND NOT EXISTS(SELECT 1 FROM gc_authority.responsibility_role_pins p_sql JOIN gc_authority.definition_heads th ON th.tenant_id=p_sql.tenant_id AND th.id=p_sql.type_id WHERE p_sql.tenant_id=t AND p_sql.role_id=i AND th.state='active'),'23514');
 END IF;PERFORM gc_authority.tick();
END $$;
CREATE FUNCTION gc_authority.validate_grant(t uuid,i uuid,read_mode boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$
DECLARE g gc_authority.grant_heads;p gc_authority.grant_heads;c gc_authority.connected_parents;o gc_authority.ordinary_role_origins;r gc_authority.responsibility_origins;rp gc_authority.responsibility_role_pins;m gc_authority.group_memberships;visited uuid[]:='{}';people uuid[]:='{}';hops integer:=0;root_role uuid;root_version integer;pol record;reg jsonb;j jsonb;own_id uuid:=i;
BEGIN
 PERFORM gc_authority.tick();SELECT * INTO g FROM gc_authority.grant_heads WHERE tenant_id=t AND id=i;PERFORM gc_authority.require(g.id IS NOT NULL,'23514');
 PERFORM gc_authority.require((SELECT count(*) FROM gc_authority.grant_human_beneficiaries WHERE tenant_id=t AND grant_id=i)=CASE g.beneficiary_kind WHEN 'human' THEN 1 ELSE 0 END AND (SELECT count(*) FROM gc_authority.grant_group_beneficiaries WHERE tenant_id=t AND grant_id=i)=CASE g.beneficiary_kind WHEN 'group' THEN 1 ELSE 0 END,'23514');
 IF g.beneficiary_kind='human' THEN PERFORM gc_authority.require(EXISTS(SELECT 1 FROM gc_authority.grant_human_beneficiaries WHERE tenant_id=t AND grant_id=i AND identity_id=g.beneficiary_id),'23514');ELSE PERFORM gc_authority.require(EXISTS(SELECT 1 FROM gc_authority.grant_group_beneficiaries WHERE tenant_id=t AND grant_id=i AND group_id=g.beneficiary_id),'23514');END IF;
 PERFORM gc_authority.require((SELECT count(*) FROM gc_authority.ordinary_role_origins WHERE tenant_id=t AND grant_id=i)=CASE g.kind WHEN 'ordinary-role' THEN 1 ELSE 0 END AND (SELECT count(*) FROM gc_authority.responsibility_origins WHERE tenant_id=t AND grant_id=i)=CASE g.kind WHEN 'responsibility' THEN 1 ELSE 0 END AND (SELECT count(*) FROM gc_authority.connected_parents WHERE tenant_id=t AND child_id=i)=CASE WHEN g.kind IN('delegation','elevation') THEN 1 ELSE 0 END,'23514');
 LOOP
 PERFORM gc_authority.require(NOT g.id=ANY(visited),'23514');visited:=array_append(visited,g.id);
 IF g.kind='ordinary-role' THEN SELECT * INTO o FROM gc_authority.ordinary_role_origins WHERE tenant_id=t AND grant_id=g.id;root_role:=o.role_id;root_version:=o.role_version;EXIT;
 ELSIF g.kind='responsibility' THEN SELECT * INTO r FROM gc_authority.responsibility_origins WHERE tenant_id=t AND grant_id=g.id;SELECT * INTO rp FROM gc_authority.responsibility_role_pins WHERE tenant_id=t AND type_id=r.type_id AND type_version=r.type_version;PERFORM gc_authority.require(rp.type_id IS NOT NULL AND (r.mapped_role_id,r.mapped_role_version) IS NOT DISTINCT FROM (rp.role_id,rp.role_version) AND ((r.mapped_role_id IS NULL AND r.effective_grant_id IS NULL AND g.control_ceiling IS NULL AND g.delegable_ceiling IS NULL) OR (r.mapped_role_id IS NOT NULL AND r.effective_grant_id=g.id)),'23514');root_role:=r.mapped_role_id;root_version:=r.mapped_role_version;EXIT;END IF;
 hops:=hops+1;PERFORM gc_authority.require(hops<=4 AND g.beneficiary_kind='human' AND NOT g.beneficiary_id=ANY(people),'23514');people:=array_append(people,g.beneficiary_id);PERFORM gc_authority.require(NOT g.issuer_identity_id=ANY(people),'23514');
 SELECT * INTO c FROM gc_authority.connected_parents WHERE tenant_id=t AND child_id=g.id;SELECT * INTO p FROM gc_authority.grant_heads WHERE tenant_id=t AND id=c.parent_id;PERFORM gc_authority.require(p.id IS NOT NULL AND p.kind<>'elevation' AND c.parent_kind=CASE p.kind WHEN 'delegation' THEN 'delegation' ELSE 'grant' END AND p.delegable_ceiling IS NOT NULL,'23514');
 IF p.beneficiary_kind='human' THEN PERFORM gc_authority.require(p.beneficiary_id=g.issuer_identity_id AND c.via_group_membership_id IS NULL,'23514');ELSE SELECT * INTO m FROM gc_authority.group_memberships WHERE tenant_id=t AND id=c.via_group_membership_id AND issuance_version=c.via_group_membership_version;PERFORM gc_authority.require(m.id IS NOT NULL AND m.group_id=p.beneficiary_id AND m.identity_id=g.issuer_identity_id,'23514');END IF;
 PERFORM gc_authority.require(gc_authority.finite_subset(g.effect_ceiling,p.effect_ceiling) AND gc_authority.finite_subset(g.effect_ceiling,p.delegable_ceiling) AND gc_authority.temporal_subset(gc_authority.validity(g.not_before,g.expires_at),gc_authority.validity(p.not_before,p.expires_at)) AND (p.delegable_ceiling->>'remainingDepth')::int>=hops AND gc_authority.scope_literal_subset(gc_authority.scope(g),gc_authority.scope(p)) AND gc_authority.scope_literal_subset(g.effect_ceiling->'scope',p.delegable_ceiling->'scope'),'23514');
 IF g.delegable_ceiling IS NOT NULL THEN PERFORM gc_authority.require(gc_authority.finite_subset(g.delegable_ceiling,p.delegable_ceiling) AND (g.delegable_ceiling->>'remainingDepth')::int<(p.delegable_ceiling->>'remainingDepth')::int,'23514');END IF;
 IF g.control_ceiling IS NOT NULL THEN PERFORM gc_authority.require(p.control_ceiling IS NOT NULL AND gc_authority.finite_subset(g.control_ceiling,p.control_ceiling) AND (NOT (g.control_ceiling->>'allowSelfBenefit')::boolean OR (p.control_ceiling->>'allowSelfBenefit')::boolean),'23514');END IF;g:=p;
 END LOOP;
 -- Exact root policy set cannot introduce service actions into a human origin.
 IF root_role IS NOT NULL THEN SELECT gc_authority.registry(registry_document) INTO reg FROM gc_authority.registries WHERE (id,version,digest)=(g.registry_id,g.registry_version,g.registry_digest);
 FOR pol IN SELECT p_sql.policy_document FROM gc_authority.role_policy_pins rp_sql JOIN gc_authority.policy_versions p_sql ON (p_sql.tenant_id,p_sql.policy_id,p_sql.version,p_sql.policy_hash)=(rp_sql.tenant_id,rp_sql.policy_id,rp_sql.policy_version,rp_sql.policy_hash) WHERE rp_sql.tenant_id=t AND rp_sql.role_id=root_role AND rp_sql.role_version=root_version LOOP j:=gc_authority.policy(pol.policy_document,reg->'fields');PERFORM gc_authority.require(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(j->'rules') rule CROSS JOIN LATERAL jsonb_array_elements_text(rule->'actions') a WHERE a=ANY(gc_authority.service_actions())),'23514');END LOOP;END IF;
 SELECT * INTO g FROM gc_authority.grant_heads WHERE tenant_id=t AND id=own_id;
 IF NOT read_mode AND g.state='active' AND (g.expires_at IS NULL OR g.expires_at>clock_timestamp()) THEN
 PERFORM gc_authority.require(g.beneficiary_kind<>'group' OR EXISTS(SELECT 1 FROM gc_authority.definition_heads h WHERE h.tenant_id=t AND h.id=g.beneficiary_id AND h.kind='group' AND h.state='active'),'23514');
 IF root_role IS NOT NULL THEN PERFORM gc_authority.require(EXISTS(SELECT 1 FROM gc_authority.definition_heads h WHERE h.tenant_id=t AND h.id=root_role AND h.kind='role' AND h.state='active') AND NOT EXISTS(SELECT 1 FROM gc_authority.role_policy_pins p_sql JOIN gc_authority.definition_heads h ON h.tenant_id=p_sql.tenant_id AND h.id=p_sql.policy_id WHERE p_sql.tenant_id=t AND p_sql.role_id=root_role AND p_sql.role_version=root_version AND h.state<>'active'),'23514');END IF;
 IF r.type_id IS NOT NULL THEN PERFORM gc_authority.require(EXISTS(SELECT 1 FROM gc_authority.definition_heads h WHERE h.tenant_id=t AND h.id=r.type_id AND h.kind='responsibility-type' AND h.state='active'),'23514');END IF;END IF;
 PERFORM gc_authority.require_measure(t,'grant',g.id,1,g.head_version,NULL,CASE g.kind WHEN 'elevation' THEN 'grant-base' ELSE 'dto' END);PERFORM gc_authority.tick();
END $$;
CREATE FUNCTION gc_authority.validate_use(t uuid,i uuid) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE u gc_authority.elevation_uses;g gc_authority.grant_heads;s gc_authn.sessions;BEGIN
 SELECT * INTO u FROM gc_authority.elevation_uses WHERE tenant_id=t AND id=i;SELECT * INTO g FROM gc_authority.grant_heads WHERE tenant_id=t AND id=u.elevation_id;SELECT * INTO s FROM gc_authn.sessions WHERE id=u.protected_session_id;
 PERFORM gc_authority.require(g.kind='elevation' AND g.beneficiary_kind='human' AND g.beneficiary_id=u.identity_id AND (s.identity_id,s.selected_tenant_id,s.generation)=(u.identity_id,u.tenant_id,u.generation) AND s.version>=u.protected_session_version AND gc_authority.temporal_subset(gc_authority.validity(u.not_before,u.expires_at),gc_authority.validity(g.not_before,g.expires_at)) AND u.expires_at<=s.expires_at,'23514');
 IF u.state='active' AND u.expires_at>clock_timestamp() THEN PERFORM gc_authority.require(NOT EXISTS(SELECT 1 FROM gc_authority.elevation_uses x WHERE x.tenant_id=t AND x.id<>i AND (x.elevation_id,x.protected_session_id,x.protected_session_version,x.generation,x.identity_id)=(u.elevation_id,u.protected_session_id,u.protected_session_version,u.generation,u.identity_id) AND x.state='active' AND x.expires_at>clock_timestamp() AND tstzrange(x.not_before,x.expires_at,'[)') && tstzrange(u.not_before,u.expires_at,'[)')),'23514');END IF;
 PERFORM gc_authority.require_measure(t,'elevation-use',i,1,u.head_version,NULL,'dto');PERFORM gc_authority.require_measure(t,'elevation-use',i,1,u.head_version,NULL,'elevation-use-embedded');END $$;
CREATE FUNCTION gc_authority.deferred_complete() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$
DECLARE b gc_authority.write_bindings;j jsonb:=to_jsonb(NEW);i uuid;head_family text;h integer;d text;body text;t uuid;BEGIN
 b:=gc_authority.sealed();t:=b.tenant_id;
 IF TG_TABLE_NAME='write_bindings' THEN PERFORM gc_authority.require(EXISTS(SELECT 1 FROM gc_authority.lifecycle_revisions WHERE tenant_id=t AND xmin=pg_current_xact_id()::xid),'23514');RETURN NULL;END IF;
 IF TG_TABLE_NAME IN('definition_heads','group_memberships','grant_heads','elevation_uses') THEN
 i:=(j->>'id')::uuid;h:=(j->>'head_version')::int;head_family:=CASE TG_TABLE_NAME WHEN 'definition_heads' THEN 'definition' WHEN 'group_memberships' THEN 'group-membership' WHEN 'grant_heads' THEN 'grant' ELSE 'elevation-use' END;
 PERFORM gc_authority.require(EXISTS(SELECT 1 FROM gc_authority.lifecycle_revisions r WHERE r.tenant_id=t AND r.family=head_family AND r.object_id=i AND r.head_version=h AND r.body_digest=gc_authority.hash(j)),'23514');
 IF head_family='definition' THEN PERFORM gc_authority.validate_definition(t,i);ELSIF head_family='grant' THEN PERFORM gc_authority.validate_grant(t,i);ELSIF head_family='elevation-use' THEN PERFORM gc_authority.validate_use(t,i);ELSE
 PERFORM gc_authority.require_measure(t,'group-membership',i,1,h,NULL,'dto');IF j->>'state'='active' AND (j->>'expires_at' IS NULL OR (j->>'expires_at')::timestamptz>clock_timestamp()) THEN PERFORM gc_authority.require(EXISTS(SELECT 1 FROM gc_authority.definition_heads h_sql WHERE h_sql.tenant_id=t AND h_sql.id=(j->>'group_id')::uuid AND h_sql.kind='group' AND h_sql.state='active'),'23514');PERFORM gc_authority.require(NOT EXISTS(SELECT 1 FROM gc_authority.group_memberships x WHERE x.tenant_id=t AND x.id<>i AND (x.group_id,x.identity_id)=((j->>'group_id')::uuid,(j->>'identity_id')::uuid) AND x.state='active' AND (x.expires_at IS NULL OR x.expires_at>clock_timestamp()) AND tstzrange(x.not_before,x.expires_at,'[)') && tstzrange((j->>'not_before')::timestamptz,(j->>'expires_at')::timestamptz,'[)')),'23514');END IF;END IF;
 ELSIF TG_TABLE_NAME IN('definition_versions','policy_versions','role_policy_pins','responsibility_role_pins','policy_deny_intents') THEN i:=CASE TG_TABLE_NAME WHEN 'role_policy_pins' THEN (j->>'role_id')::uuid WHEN 'responsibility_role_pins' THEN (j->>'type_id')::uuid ELSE coalesce((j->>'id')::uuid,(j->>'policy_id')::uuid) END;PERFORM gc_authority.validate_definition(t,i);
 ELSIF TG_TABLE_NAME IN('grant_human_beneficiaries','grant_group_beneficiaries','ordinary_role_origins','responsibility_origins','connected_parents') THEN i:=coalesce((j->>'grant_id')::uuid,(j->>'child_id')::uuid);PERFORM gc_authority.validate_grant(t,i);END IF;
 PERFORM gc_authority.tick();RETURN NULL;
END $$;
CREATE FUNCTION gc_authority.ref_key(r jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT (r->>'kind')||':'||(r->>'id')||'@'||(r->>'version') $$;
CREATE FUNCTION gc_authority.closure_key(identity_id uuid,request jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT gc_authority.hash(jsonb_build_object('formatVersion',1,'subject',jsonb_build_object('kind','human','id',identity_id),'request',request)) $$;
CREATE FUNCTION gc_authority.root_origin(t uuid,i uuid) RETURNS gc_authority.grant_heads LANGUAGE plpgsql STABLE SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE g gc_authority.grant_heads;seen uuid[]:='{}';p uuid;BEGIN LOOP
 PERFORM gc_authority.tick();PERFORM gc_authority.require(NOT i=ANY(seen) AND cardinality(seen)<=4,'23514');seen:=array_append(seen,i);SELECT x.id,x.kind INTO g.id,g.kind FROM gc_authority.grant_heads x WHERE x.tenant_id=t AND x.id=i;PERFORM gc_authority.require(g.id IS NOT NULL,'23514');IF g.kind IN('ordinary-role','responsibility') THEN RETURN g;END IF;SELECT parent_id INTO p FROM gc_authority.connected_parents WHERE tenant_id=t AND child_id=i;PERFORM gc_authority.require(p IS NOT NULL,'23514');i:=p;END LOOP;END $$;
CREATE FUNCTION gc_authority.has_intent(t uuid,i uuid,resource_kind text) RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE g gc_authority.grant_heads;r uuid;v integer;BEGIN
 g:=gc_authority.root_origin(t,i);IF g.kind='ordinary-role' THEN SELECT role_id,role_version INTO r,v FROM gc_authority.ordinary_role_origins WHERE tenant_id=t AND grant_id=g.id;ELSE SELECT mapped_role_id,mapped_role_version INTO r,v FROM gc_authority.responsibility_origins WHERE tenant_id=t AND grant_id=g.id;END IF;
 RETURN EXISTS(SELECT 1 FROM gc_authority.role_policy_pins p JOIN gc_authority.policy_deny_intents d ON (d.tenant_id,d.policy_id,d.policy_version,d.policy_hash)=(p.tenant_id,p.policy_id,p.policy_version,p.policy_hash) WHERE p.tenant_id=t AND p.role_id=r AND p.role_version=v AND resource_kind=ANY(d.resource_kinds));END $$;
CREATE FUNCTION gc_authority.dependency_depth(node text,deps jsonb,stack text[] DEFAULT '{}') RETURNS integer LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ DECLARE x jsonb;d integer:=1;BEGIN
 PERFORM gc_authority.require(NOT node=ANY(stack),'23514');PERFORM gc_authority.require(cardinality(stack)<16,'54000');stack:=array_append(stack,node);FOR x IN SELECT value FROM jsonb_array_elements(deps) WHERE value->>'from'=node LOOP d:=greatest(d,1+gc_authority.dependency_depth(x->>'issuer',deps,stack));END LOOP;RETURN d;END $$;
CREATE FUNCTION gc_authority.read_head_valid(t uuid,f text,i uuid,h integer) RETURNS void LANGUAGE plpgsql STABLE SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$
DECLARE j jsonb;BEGIN PERFORM gc_authority.tick();CASE f WHEN 'definition' THEN SELECT to_jsonb(x) INTO j FROM gc_authority.definition_heads x WHERE tenant_id=t AND id=i;WHEN 'grant' THEN SELECT to_jsonb(x) INTO j FROM gc_authority.grant_heads x WHERE tenant_id=t AND id=i;WHEN 'group-membership' THEN SELECT to_jsonb(x) INTO j FROM gc_authority.group_memberships x WHERE tenant_id=t AND id=i;WHEN 'elevation-use' THEN SELECT to_jsonb(x) INTO j FROM gc_authority.elevation_uses x WHERE tenant_id=t AND id=i;ELSE PERFORM gc_authority.require(false,'23514');END CASE;
 PERFORM gc_authority.require(j IS NOT NULL AND (j->>'head_version')::int=h AND EXISTS(SELECT 1 FROM gc_authority.lifecycle_revisions r WHERE r.tenant_id=t AND r.family=f AND r.object_id=i AND r.head_version=h AND r.definition_kind IS NOT DISTINCT FROM CASE f WHEN 'definition' THEN j->>'kind' ELSE NULL END AND r.definition_version IS NOT DISTINCT FROM (j->>'definition_version')::int AND r.state=j->>'state' AND r.changed_at=(j->>'changed_at')::timestamptz AND r.body_digest=gc_authority.hash(j)),'23514');END $$;
CREATE FUNCTION gc_authority.measure_key_cost(t uuid,added jsonb) RETURNS bigint[] LANGUAGE plpgsql STABLE SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$
DECLARE k jsonb;m gc_authority.projection_measures;b bigint:=0;n bigint:=0;BEGIN
 PERFORM gc_authority.tick();FOR k IN SELECT value FROM jsonb_array_elements(added) LOOP SELECT * INTO m FROM gc_authority.projection_measures WHERE tenant_id=t AND family=k->>'family' AND object_id=(k->>'id')::uuid AND issuance_or_definition_version=(k->>'version')::int AND head_version=(k->>'head')::int AND projection_form=k->>'form' AND sub_id IS NULL;PERFORM gc_authority.require(m.id IS NOT NULL,'23514');b:=b+m.canonical_bytes+m.raw_bytes;n:=n+m.json_nodes;END LOOP;RETURN ARRAY[b,n];
END $$;
CREATE FUNCTION gc_authority.load_human_closure_v1(session_hash text,selectors_text text) RETURNS jsonb LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$
DECLARE
 auth gc_authn.foundation_session;check_auth gc_authn.foundation_session;th gc_authority.tenant_heads;reg gc_authority.registries;registry jsonb;selectors jsonb;as_of timestamptz:=date_trunc('milliseconds',transaction_timestamp());old_t text:=current_setting('gc.tenant_id',true);old_a text:=current_setting('gc.actor_id',true);
 queue jsonb:='[]';partitions jsonb:='[]';parents jsonb:='[]';dependencies jsonb:='[]';principals jsonb:='[]';groups jsonb:='[]';memberships jsonb:='[]';principal_groups jsonb:='[]';definitions jsonb:='[]';policies jsonb:='[]';grants jsonb:='[]';uses jsonb:='[]';lifecycle jsonb:='[]';identity_inventory jsonb:='[]';measure_keys jsonb:='[]';definitions_keys jsonb:='[]';policy_keys jsonb:='[]';session_dto jsonb;out_value jsonb;metrics jsonb;
 all_people uuid[]:='{}';partition_people uuid[]:='{}';all_groups uuid[]:='{}';all_memberships uuid[]:='{}';all_grants uuid[]:='{}';all_uses uuid[]:='{}';seen_parents uuid[]:='{}';candidate_ids uuid[];subject_groups uuid[];subject_memberships uuid[];chain_ids uuid[];queue_keys text[]:='{}';all_definition_keys text[]:='{}';all_policy_keys text[]:='{}';
 part jsonb;req jsonb;candidate_refs jsonb;subject uuid;key text;issuer_key text;pk text;dk text;dep jsonb;mk jsonb;projection jsonb;expected_projection jsonb;person gc_authority.identity_heads;member gc_authority.tenant_member_heads;g gc_authority.grant_heads;child gc_authority.grant_heads;c gc_authority.connected_parents;m gc_authority.group_memberships;h gc_authority.definition_heads;u gc_authority.elevation_uses;origin gc_authority.grant_heads;selected_role_id uuid;selected_role_version integer;type_id uuid;type_version integer;p gc_authority.policy_versions;pm gc_authority.projection_measures;d gc_authority.definition_versions;row record;item jsonb;i uuid;v integer;idx integer:=0;visits bigint:=0;depth integer:=0;
 key_bytes bigint:=0;key_nodes bigint:=0;estimated_bytes bigint:=0;estimated_nodes bigint:=0;proof_bytes bigint:=0;raw_policy_bytes bigint:=0;policy_bytes bigint:=0;policy_rules integer:=0;expression_nodes integer:=0;direct_max integer:=0;origins integer:=0;connected integer:=0;physical bigint[];canonical_bytes bigint:=0;previous_bytes bigint:=-1;round integer;
BEGIN
 PERFORM gc_authority.owner_check();PERFORM gc_authority.tick();auth:=gc_authn.foundation_session_v1(session_hash);PERFORM set_config('gc.tenant_id',auth.tenant_id::text,true);PERFORM set_config('gc.actor_id',auth.identity_id::text,true);
 SELECT * INTO th FROM gc_authority.tenant_heads WHERE tenant_id=auth.tenant_id;PERFORM gc_authority.require(th.tenant_id IS NOT NULL AND th.mode='inactive' AND th.generation=auth.generation,'28000');
 -- Scalar byte/count admission precedes reading the registry body.
 SELECT octet_length(r.registry_document) AS raw,r.canonical_bytes,r.json_nodes INTO row FROM gc_authority.registries r WHERE (r.id,r.version,r.digest)=(th.registry_id,th.registry_version,th.registry_digest);PERFORM gc_authority.require(FOUND AND row.raw+row.canonical_bytes<=8388608 AND row.json_nodes<=262144,'54000');
 SELECT * INTO reg FROM gc_authority.registries WHERE (id,version,digest)=(th.registry_id,th.registry_version,th.registry_digest);registry:=gc_authority.registry(reg.registry_document);PERFORM gc_authority.require(registry->>'digest'=reg.digest AND (registry->>'version')::int=reg.version AND reg.canonical_bytes=octet_length(gc_authority.canonical(registry)) AND reg.json_nodes=(gc_authority.json_measure(registry))[1],'23514');
 selectors:=gc_authority.normalize(gc_authority.parse(selectors_text,131072),'"selectors"',registry->'fields')->'requests';
 FOR req IN SELECT value FROM jsonb_array_elements(selectors) LOOP
 PERFORM gc_authority.require((req#>>'{resource,tenantId}')::uuid=auth.tenant_id AND NOT req->>'action'=ANY(gc_authority.service_actions()) AND ((req->>'action'=ANY(gc_authority.field_actions()))=(req->'field'<>'null'::jsonb)));
 key:=gc_authority.closure_key(auth.identity_id,req);queue:=queue||jsonb_build_array(jsonb_build_object('key',key,'subject',jsonb_build_object('kind','human','id',auth.identity_id),'request',req));queue_keys:=array_append(queue_keys,key);END LOOP;
 -- Only bounded scalar identities and literal selectors are retained in discovery.
 WHILE idx<jsonb_array_length(queue) LOOP
 PERFORM gc_authority.tick();part:=queue->idx;idx:=idx+1;subject:=(part#>>'{subject,id}')::uuid;req:=part->'request';key:=part->>'key';candidate_refs:='[]';candidate_ids:='{}';
 IF NOT subject=ANY(all_people) THEN all_people:=array_append(all_people,subject);END IF;IF NOT subject=ANY(partition_people) THEN partition_people:=array_append(partition_people,subject);END IF;
 subject_groups:='{}';subject_memberships:='{}';FOR row IN SELECT id,group_id FROM gc_authority.group_memberships WHERE tenant_id=auth.tenant_id AND identity_id=subject AND state='active' AND (expires_at IS NULL OR expires_at>as_of) ORDER BY id LOOP
 visits:=visits+1;IF visits%64=0 THEN PERFORM gc_authority.tick();END IF;subject_memberships:=array_append(subject_memberships,row.id);PERFORM gc_authority.require(cardinality(subject_memberships)<=1024,'54000');IF NOT row.group_id=ANY(subject_groups) THEN subject_groups:=array_append(subject_groups,row.group_id);END IF;IF NOT row.id=ANY(all_memberships) THEN all_memberships:=array_append(all_memberships,row.id);PERFORM gc_authority.require(cardinality(all_memberships)*160::bigint<=2097152,'54000');END IF;IF NOT row.group_id=ANY(all_groups) THEN all_groups:=array_append(all_groups,row.group_id);END IF;END LOOP;
 FOR row IN SELECT id,kind,pg_column_size(effect_ceiling) AS size FROM gc_authority.grant_heads WHERE tenant_id=auth.tenant_id AND state='active' AND (expires_at IS NULL OR expires_at>as_of) AND ((beneficiary_kind='human' AND beneficiary_id=subject) OR (beneficiary_kind='group' AND beneficiary_id=ANY(subject_groups))) ORDER BY id LOOP
 visits:=visits+1;IF visits%64=0 THEN PERFORM gc_authority.tick();END IF;PERFORM gc_authority.require(row.size<=8388608,'54000');
 IF EXISTS(SELECT 1 FROM gc_authority.grant_heads x WHERE x.tenant_id=auth.tenant_id AND x.id=row.id AND (x.effect_ceiling->'actions') @> jsonb_build_array(req->'action') AND (x.effect_ceiling->'resourceKinds') @> jsonb_build_array(req#>'{resource,kind}') AND (req->'field'='null'::jsonb OR x.effect_ceiling->'fields'='null'::jsonb OR (x.effect_ceiling->'fields') @> jsonb_build_array(req->'field'))) OR gc_authority.has_intent(auth.tenant_id,row.id,req#>>'{resource,kind}') THEN candidate_ids:=array_append(candidate_ids,row.id);PERFORM gc_authority.require(cardinality(candidate_ids)<=1536,'54000');END IF;END LOOP;
 FOREACH i IN ARRAY candidate_ids LOOP
 SELECT jsonb_build_object('kind',CASE WHEN kind IN('delegation','elevation') THEN kind ELSE 'grant' END,'id',id,'version',1) INTO item FROM gc_authority.grant_heads WHERE tenant_id=auth.tenant_id AND id=i;candidate_refs:=candidate_refs||jsonb_build_array(item);chain_ids:='{}';
 LOOP
 PERFORM gc_authority.tick();PERFORM gc_authority.require(NOT i=ANY(chain_ids) AND cardinality(chain_ids)<=4,'23514');chain_ids:=array_append(chain_ids,i);
 IF NOT i=ANY(all_grants) THEN all_grants:=array_append(all_grants,i);PERFORM gc_authority.require(cardinality(all_grants)<=1536,'54000');END IF;
 -- Fixed scalar fields only; payloads are loaded after complete preflight.
 SELECT id,kind,issuer_identity_id,beneficiary_kind,beneficiary_id,head_version INTO row FROM gc_authority.grant_heads WHERE tenant_id=auth.tenant_id AND id=i;PERFORM gc_authority.require(FOUND,'23514');
 IF NOT row.issuer_identity_id=ANY(all_people) THEN all_people:=array_append(all_people,row.issuer_identity_id);END IF;IF row.beneficiary_kind='human' THEN IF NOT row.beneficiary_id=ANY(all_people) THEN all_people:=array_append(all_people,row.beneficiary_id);END IF;ELSE IF NOT row.beneficiary_id=ANY(all_groups) THEN all_groups:=array_append(all_groups,row.beneficiary_id);END IF;END IF;
 PERFORM gc_authority.require(cardinality(all_people)<=2048,'54000');
 IF row.kind IN('ordinary-role','responsibility') THEN
 selected_role_id:=NULL;selected_role_version:=NULL;type_id:=NULL;type_version:=NULL;
 IF row.kind='ordinary-role' THEN SELECT o.role_id,o.role_version INTO selected_role_id,selected_role_version FROM gc_authority.ordinary_role_origins o WHERE o.tenant_id=auth.tenant_id AND o.grant_id=i;PERFORM gc_authority.require(FOUND,'23514');ELSE SELECT r.type_id,r.type_version,r.mapped_role_id,r.mapped_role_version INTO type_id,type_version,selected_role_id,selected_role_version FROM gc_authority.responsibility_origins r WHERE r.tenant_id=auth.tenant_id AND r.grant_id=i;PERFORM gc_authority.require(FOUND,'23514');END IF;
 IF type_id IS NOT NULL THEN dk:='responsibility-type:'||type_id::text||'@'||type_version::text;IF NOT dk=ANY(all_definition_keys) THEN all_definition_keys:=array_append(all_definition_keys,dk);definitions_keys:=definitions_keys||jsonb_build_array(jsonb_build_object('kind','responsibility-type','id',type_id,'version',type_version));END IF;END IF;
 IF selected_role_id IS NOT NULL THEN dk:='role:'||selected_role_id::text||'@'||selected_role_version::text;IF NOT dk=ANY(all_definition_keys) THEN all_definition_keys:=array_append(all_definition_keys,dk);definitions_keys:=definitions_keys||jsonb_build_array(jsonb_build_object('kind','role','id',selected_role_id,'version',selected_role_version));END IF;
 FOR row IN SELECT policy_id,policy_version,policy_hash FROM gc_authority.role_policy_pins rp WHERE rp.tenant_id=auth.tenant_id AND rp.role_id=selected_role_id AND rp.role_version=selected_role_version ORDER BY rp.ordinal LOOP pk:=row.policy_id::text||'@'||row.policy_version::text||'#'||row.policy_hash;IF NOT pk=ANY(all_policy_keys) THEN all_policy_keys:=array_append(all_policy_keys,pk);policy_keys:=policy_keys||jsonb_build_array(jsonb_build_object('policyId',row.policy_id,'version',row.policy_version,'hash',row.policy_hash));PERFORM gc_authority.require(cardinality(all_policy_keys)<=32,'54000');END IF;END LOOP;END IF;EXIT;END IF;
 SELECT * INTO c FROM gc_authority.connected_parents WHERE tenant_id=auth.tenant_id AND child_id=i;PERFORM gc_authority.require(c.child_id IS NOT NULL,'23514');
 IF NOT i=ANY(seen_parents) THEN seen_parents:=array_append(seen_parents,i);parents:=parents||jsonb_build_array(jsonb_build_object('child',jsonb_build_object('kind',row.kind,'id',i,'version',1),'parent',jsonb_build_object('kind',c.parent_kind,'id',c.parent_id,'version',1),'viaMembership',CASE WHEN c.via_group_membership_id IS NULL THEN NULL ELSE jsonb_build_object('id',c.via_group_membership_id,'version',c.via_group_membership_version) END));END IF;
 IF c.via_group_membership_id IS NOT NULL THEN IF NOT c.via_group_membership_id=ANY(all_memberships) THEN all_memberships:=array_append(all_memberships,c.via_group_membership_id);PERFORM gc_authority.require(cardinality(all_memberships)*160::bigint<=2097152,'54000');END IF;SELECT group_id,identity_id INTO row FROM gc_authority.group_memberships WHERE tenant_id=auth.tenant_id AND id=c.via_group_membership_id;PERFORM gc_authority.require(FOUND,'23514');IF NOT row.group_id=ANY(all_groups) THEN all_groups:=array_append(all_groups,row.group_id);END IF;IF NOT row.identity_id=ANY(all_people) THEN all_people:=array_append(all_people,row.identity_id);END IF;END IF;
 SELECT issuer_identity_id,kind INTO row FROM gc_authority.grant_heads WHERE tenant_id=auth.tenant_id AND id=i;issuer_key:=gc_authority.closure_key(row.issuer_identity_id,req);dep:=jsonb_build_object('from',key,'issuer',issuer_key,'child',jsonb_build_object('kind',row.kind,'id',i,'version',1));IF NOT dependencies @> jsonb_build_array(dep) THEN dependencies:=dependencies||jsonb_build_array(dep);PERFORM gc_authority.require(jsonb_array_length(dependencies)<=4096,'54000');END IF;
 IF NOT issuer_key=ANY(queue_keys) THEN queue_keys:=array_append(queue_keys,issuer_key);queue:=queue||jsonb_build_array(jsonb_build_object('key',issuer_key,'subject',jsonb_build_object('kind','human','id',row.issuer_identity_id),'request',req));PERFORM gc_authority.require(jsonb_array_length(queue)<=128,'54000');END IF;i:=c.parent_id;END LOOP;
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY gc_authority.ref_key(value) COLLATE "C"),'[]') INTO candidate_refs FROM jsonb_array_elements(candidate_refs);partitions:=partitions||jsonb_build_array(part||jsonb_build_object('candidates',candidate_refs));
 PERFORM gc_authority.require(cardinality(all_memberships)*40::bigint+cardinality(all_groups)*40::bigint+cardinality(all_people)*40::bigint+octet_length(gc_authority.canonical(queue))+octet_length(gc_authority.canonical(parents))+octet_length(gc_authority.canonical(dependencies))<=8388608,'54000');PERFORM gc_authority.tick();END LOOP;
 PERFORM gc_authority.require((SELECT count(DISTINCT (value->>'from',value->>'issuer')) FROM jsonb_array_elements(dependencies))<=1024,'54000');
 FOR part IN SELECT value FROM jsonb_array_elements(partitions) LOOP depth:=greatest(depth,gc_authority.dependency_depth(part->>'key',dependencies));END LOOP;
 -- Complete inventories are preflighted with stored independently verified measures.
 SELECT count(*) FILTER(WHERE kind IN('ordinary-role','responsibility')),count(*) FILTER(WHERE kind IN('delegation','elevation')) INTO origins,connected FROM gc_authority.grant_heads WHERE tenant_id=auth.tenant_id AND id=ANY(all_grants);PERFORM gc_authority.require(origins<=512 AND connected<=1024,'54000');
 FOR row IN SELECT id,head_version,kind FROM gc_authority.grant_heads WHERE tenant_id=auth.tenant_id AND id=ANY(all_grants) LOOP item:=jsonb_build_array(jsonb_build_object('family','grant','id',row.id,'version',1,'head',row.head_version,'form',CASE row.kind WHEN 'elevation' THEN 'grant-base' ELSE 'dto' END));physical:=gc_authority.measure_key_cost(auth.tenant_id,item);key_bytes:=key_bytes+physical[1];key_nodes:=key_nodes+physical[2];PERFORM gc_authority.require(key_bytes<=8388608 AND key_nodes<=262144,'54000');measure_keys:=measure_keys||item;END LOOP;
 FOR row IN SELECT id,head_version FROM gc_authority.group_memberships WHERE tenant_id=auth.tenant_id AND id=ANY(all_memberships) LOOP item:=jsonb_build_array(jsonb_build_object('family','group-membership','id',row.id,'version',1,'head',row.head_version,'form','dto'));physical:=gc_authority.measure_key_cost(auth.tenant_id,item);key_bytes:=key_bytes+physical[1];key_nodes:=key_nodes+physical[2];PERFORM gc_authority.require(key_bytes<=8388608 AND key_nodes<=262144,'54000');measure_keys:=measure_keys||item;END LOOP;
 FOR row IN SELECT id,definition_version,head_version FROM gc_authority.definition_heads WHERE tenant_id=auth.tenant_id AND kind='group' AND id=ANY(all_groups) LOOP item:=jsonb_build_array(jsonb_build_object('family','group','id',row.id,'version',row.definition_version,'head',row.head_version,'form','dto'));physical:=gc_authority.measure_key_cost(auth.tenant_id,item);key_bytes:=key_bytes+physical[1];key_nodes:=key_nodes+physical[2];PERFORM gc_authority.require(key_bytes<=8388608 AND key_nodes<=262144,'54000');measure_keys:=measure_keys||item;END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(definitions_keys) LOOP SELECT head_version INTO v FROM gc_authority.definition_heads WHERE tenant_id=auth.tenant_id AND id=(item->>'id')::uuid;item:=jsonb_build_array(jsonb_build_object('family','definition','id',item->'id','version',item->'version','head',v,'form','dto'));physical:=gc_authority.measure_key_cost(auth.tenant_id,item);key_bytes:=key_bytes+physical[1];key_nodes:=key_nodes+physical[2];PERFORM gc_authority.require(key_bytes<=8388608 AND key_nodes<=262144,'54000');measure_keys:=measure_keys||item;END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(policy_keys) LOOP SELECT head_version INTO v FROM gc_authority.definition_heads WHERE tenant_id=auth.tenant_id AND id=(item->>'policyId')::uuid;
 SELECT pv_sql.canonical_bytes,octet_length(pv_sql.policy_document) AS raw,pv_sql.rule_count,pv_sql.expression_node_count INTO row FROM gc_authority.policy_versions pv_sql WHERE pv_sql.tenant_id=auth.tenant_id AND pv_sql.policy_id=(item->>'policyId')::uuid AND pv_sql.version=(item->>'version')::int;
 PERFORM gc_authority.require(FOUND,'23514');policy_bytes:=policy_bytes+row.canonical_bytes;raw_policy_bytes:=raw_policy_bytes+row.raw;policy_rules:=policy_rules+row.rule_count;expression_nodes:=expression_nodes+row.expression_node_count;PERFORM gc_authority.require(policy_bytes<=2097152 AND policy_rules<=4096 AND expression_nodes<=4096,'54000');item:=jsonb_build_array(jsonb_build_object('family','policy','id',item->'policyId','version',item->'version','head',v,'form','dto'));physical:=gc_authority.measure_key_cost(auth.tenant_id,item);key_bytes:=key_bytes+physical[1];key_nodes:=key_nodes+physical[2];PERFORM gc_authority.require(key_bytes<=8388608 AND key_nodes<=262144,'54000');measure_keys:=measure_keys||item;END LOOP;
 -- Keep every future/current exact-session use. Other identities' uses remain
 -- supplemental evidence; no issuer partition borrows the root authentication.
 FOR row IN SELECT id,head_version FROM gc_authority.elevation_uses WHERE tenant_id=auth.tenant_id AND elevation_id=ANY(all_grants) AND state='active' AND expires_at>as_of ORDER BY id LOOP
 all_uses:=array_append(all_uses,row.id);PERFORM gc_authority.require(cardinality(all_uses)<=262144,'54000');item:=jsonb_build_array(jsonb_build_object('family','elevation-use','id',row.id,'version',1,'head',row.head_version,'form','dto'),jsonb_build_object('family','elevation-use','id',row.id,'version',1,'head',row.head_version,'form','elevation-use-embedded'));physical:=gc_authority.measure_key_cost(auth.tenant_id,item);key_bytes:=key_bytes+physical[1];key_nodes:=key_nodes+physical[2];PERFORM gc_authority.require(key_bytes<=8388608 AND key_nodes<=262144,'54000');measure_keys:=measure_keys||item;END LOOP;
 -- Conservative framing reserves bound unmaterialized primitive projections.
 estimated_bytes:=octet_length(gc_authority.canonical(partitions))+octet_length(gc_authority.canonical(parents))+octet_length(gc_authority.canonical(dependencies))+cardinality(all_people)*4096::bigint+cardinality(all_groups)*512::bigint+cardinality(all_memberships)*256::bigint+cardinality(all_grants)*512::bigint+cardinality(all_uses)*512::bigint+65536;
 estimated_nodes:=cardinality(all_people)*64::bigint+cardinality(all_groups)*16::bigint+cardinality(all_memberships)*16::bigint+cardinality(all_grants)*32::bigint+cardinality(all_uses)*32::bigint+4096;
 FOR mk IN SELECT value FROM jsonb_array_elements(measure_keys) LOOP
 visits:=visits+1;IF visits%64=0 THEN PERFORM gc_authority.tick();END IF;
 SELECT * INTO pm FROM gc_authority.projection_measures WHERE tenant_id=auth.tenant_id AND family=mk->>'family' AND object_id=(mk->>'id')::uuid AND issuance_or_definition_version=(mk->>'version')::int AND head_version=(mk->>'head')::int AND projection_form=mk->>'form' AND sub_id IS NULL;PERFORM gc_authority.require(pm.id IS NOT NULL,'23514');estimated_bytes:=estimated_bytes+pm.canonical_bytes+pm.raw_bytes;estimated_nodes:=estimated_nodes+pm.json_nodes;PERFORM gc_authority.require(estimated_bytes<=8388608 AND estimated_nodes<=262144,'54000');END LOOP;
 -- Fixed identities are checked against current canonical columns before JSON.
 FOREACH i IN ARRAY all_people LOOP
 SELECT octet_length(coalesce(canonical_issuer,''))+octet_length(coalesce(canonical_subject,'')) AS retained INTO row FROM gc_authority.identity_heads WHERE identity_id=i;PERFORM gc_authority.require(FOUND,'23514');PERFORM gc_authority.require(row.retained<=8388608 AND estimated_bytes+row.retained*6<=8388608,'54000');estimated_bytes:=estimated_bytes+row.retained*6;
 SELECT * INTO person FROM gc_authority.identity_heads WHERE identity_id=i;PERFORM gc_authority.require(person.identity_id IS NOT NULL,'23514');
 PERFORM gc_authority.require((person.present AND EXISTS(SELECT 1 FROM public.identities x WHERE x.id=i AND (x.issuer,x.subject,x.active) IS NOT DISTINCT FROM (person.canonical_issuer,person.canonical_subject,person.active))) OR (NOT person.present AND NOT EXISTS(SELECT 1 FROM public.identities WHERE id=i)),'23514');
 PERFORM gc_authority.require(person.row_digest=gc_authority.hash(jsonb_build_object('identityId',person.identity_id,'present',person.present,'canonicalIssuer',person.canonical_issuer,'canonicalSubject',person.canonical_subject,'active',person.active)),'23514');
 SELECT * INTO member FROM gc_authority.tenant_member_heads WHERE tenant_id=auth.tenant_id AND identity_id=i;IF member.identity_id IS NOT NULL THEN PERFORM gc_authority.require(member.row_digest=gc_authority.hash(jsonb_build_object('tenantId',member.tenant_id,'identityId',member.identity_id,'present',member.present,'active',member.active)),'23514');PERFORM gc_authority.require((member.present AND EXISTS(SELECT 1 FROM public.memberships x WHERE x.tenant_id=auth.tenant_id AND x.identity_id=i AND x.active=member.active)) OR (NOT member.present AND NOT EXISTS(SELECT 1 FROM public.memberships WHERE tenant_id=auth.tenant_id AND identity_id=i)),'23514');ELSE PERFORM gc_authority.require(NOT EXISTS(SELECT 1 FROM public.memberships WHERE tenant_id=auth.tenant_id AND identity_id=i),'23514');END IF;
 principals:=principals||jsonb_build_array(jsonb_build_object('kind','human','id',i,'identityRevision',person.revision::text,'active',person.present AND person.active,'membership',CASE WHEN member.identity_id IS NULL THEN NULL ELSE jsonb_build_object('ref',jsonb_build_object('id',member.membership_id,'version',member.revision),'tenantId',auth.tenant_id,'identityId',i,'state',CASE WHEN member.present AND member.active THEN 'active' ELSE 'revoked' END,'validity',gc_authority.validity(NULL,NULL)) END));
 identity_inventory:=identity_inventory||jsonb_build_array(jsonb_build_object('identity',jsonb_set(to_jsonb(person),'{revision}',to_jsonb(person.revision::text)),'membership',CASE WHEN member.identity_id IS NULL THEN NULL ELSE to_jsonb(member) END));END LOOP;
 FOREACH i IN ARRAY partition_people LOOP SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'version',issuance_version) ORDER BY id::text||'@'||issuance_version::text),'[]'),count(*) INTO item,v FROM gc_authority.group_memberships WHERE tenant_id=auth.tenant_id AND identity_id=i AND id=ANY(all_memberships);direct_max:=greatest(direct_max,v);PERFORM gc_authority.require(v<=1024,'54000');principal_groups:=principal_groups||jsonb_build_array(jsonb_build_object('subject',jsonb_build_object('kind','human','id',i),'memberships',jsonb_build_object('status','known','value',item)));END LOOP;
 PERFORM gc_authority.tick();
 FOR mk IN SELECT value FROM jsonb_array_elements(measure_keys) LOOP
 PERFORM gc_authority.read_head_valid(auth.tenant_id,CASE WHEN mk->>'family' IN('policy','definition','group') THEN 'definition' ELSE mk->>'family' END,(mk->>'id')::uuid,(mk->>'head')::int);
 projection:=gc_authority.projection_v1(auth.tenant_id,mk->>'family',(mk->>'id')::uuid,(mk->>'version')::int,(mk->>'head')::int,NULL,mk->>'form');physical:=gc_authority.json_measure(projection);
 SELECT * INTO pm FROM gc_authority.projection_measures WHERE tenant_id=auth.tenant_id AND family=mk->>'family' AND object_id=(mk->>'id')::uuid AND issuance_or_definition_version=(mk->>'version')::int AND head_version=(mk->>'head')::int AND projection_form=mk->>'form' AND sub_id IS NULL;
 PERFORM gc_authority.require(pm.projection_hash=gc_authority.hash(projection) AND pm.canonical_bytes=octet_length(gc_authority.canonical(projection)) AND pm.json_nodes=physical[1] AND pm.json_depth=physical[2],'23514');
 IF mk->>'family'='definition' THEN PERFORM gc_authority.require(projection->>'hash'=gc_authority.hash(projection-ARRAY['tenantId','currentHeadVersion','state','hash']),'23514');
 ELSIF mk->>'family'='policy' THEN expected_projection:=gc_authority.policy(projection->>'document',registry->'fields');PERFORM gc_authority.require((expected_projection->>'id',expected_projection->>'version',gc_authority.hash(expected_projection))=(projection#>>'{pin,policyId}',projection#>>'{pin,version}',projection#>>'{pin,hash}'),'23514');
 ELSIF mk->>'family'='group' THEN SELECT * INTO h FROM gc_authority.definition_heads WHERE tenant_id=auth.tenant_id AND id=(mk->>'id')::uuid;SELECT * INTO d FROM gc_authority.definition_versions WHERE tenant_id=auth.tenant_id AND id=h.id AND version=h.definition_version;PERFORM gc_authority.require(d.semantic_hash=gc_authority.hash(jsonb_build_object('formatVersion',1,'kind','group','id',h.id,'version',d.version,'content',jsonb_build_object('metadata',jsonb_build_object('key',h.key,'label',d.label,'description',d.description)))),'23514');
 ELSIF mk->>'family'='grant' THEN PERFORM gc_authority.validate_grant(auth.tenant_id,(mk->>'id')::uuid,true);
 ELSIF mk->>'family'='elevation-use' THEN PERFORM gc_authority.validate_use(auth.tenant_id,(mk->>'id')::uuid);END IF;
 CASE mk->>'family' WHEN 'definition' THEN definitions:=definitions||jsonb_build_array(projection);WHEN 'policy' THEN policies:=policies||jsonb_build_array(projection);WHEN 'group' THEN groups:=groups||jsonb_build_array(projection);WHEN 'group-membership' THEN memberships:=memberships||jsonb_build_array(projection);WHEN 'elevation-use' THEN IF mk->>'form'='dto' THEN uses:=uses||jsonb_build_array(projection);END IF;
 WHEN 'grant' THEN IF mk->>'form'='grant-base' THEN SELECT * INTO u FROM gc_authority.elevation_uses WHERE tenant_id=auth.tenant_id AND elevation_id=(mk->>'id')::uuid AND id=ANY(all_uses) AND protected_session_id=auth.session_id AND protected_session_version=auth.session_version AND generation=auth.generation AND identity_id=auth.identity_id ORDER BY CASE WHEN not_before IS NULL OR not_before<=as_of THEN 0 ELSE 1 END,not_before NULLS FIRST,id,issuance_version LIMIT 1;
 IF u.id IS NULL THEN projection:=projection||jsonb_build_object('use',NULL);ELSE projection:=projection||jsonb_build_object('use',gc_authority.projection_v1(auth.tenant_id,'elevation-use',u.id,1,u.head_version,NULL,'elevation-use-embedded'));END IF;END IF;grants:=grants||jsonb_build_array(projection);END CASE;
 visits:=visits+1;IF visits%64=0 THEN PERFORM gc_authority.tick();END IF;END LOOP;
 -- Current lifecycle inventory contains one row per retained canonical head.
 SELECT coalesce(jsonb_agg(value ORDER BY value->>'family',coalesce(value->>'definitionKind',''),value->>'id'),'[]') INTO lifecycle FROM (
 SELECT jsonb_build_object('family','definition','id',h_sql.id,'definitionKind',h_sql.kind,'headVersion',h_sql.head_version) AS value FROM gc_authority.definition_heads h_sql WHERE h_sql.tenant_id=auth.tenant_id AND (h_sql.id=ANY(all_groups) OR EXISTS(SELECT 1 FROM jsonb_array_elements(definitions_keys)x WHERE x->>'id'=h_sql.id::text) OR EXISTS(SELECT 1 FROM jsonb_array_elements(policy_keys)x WHERE x->>'policyId'=h_sql.id::text))
 UNION ALL SELECT jsonb_build_object('family','grant','id',id,'definitionKind',NULL,'headVersion',head_version) FROM gc_authority.grant_heads WHERE tenant_id=auth.tenant_id AND id=ANY(all_grants)
 UNION ALL SELECT jsonb_build_object('family','group-membership','id',id,'definitionKind',NULL,'headVersion',head_version) FROM gc_authority.group_memberships WHERE tenant_id=auth.tenant_id AND id=ANY(all_memberships)
 UNION ALL SELECT jsonb_build_object('family','elevation-use','id',id,'definitionKind',NULL,'headVersion',head_version) FROM gc_authority.elevation_uses WHERE tenant_id=auth.tenant_id AND id=ANY(all_uses)) x;
 SELECT coalesce(jsonb_agg(value ORDER BY value->>'key'),'[]') INTO partitions FROM jsonb_array_elements(partitions);
 SELECT coalesce(jsonb_agg(value ORDER BY gc_authority.ref_key(value->'child')),'[]') INTO parents FROM jsonb_array_elements(parents);
 SELECT coalesce(jsonb_agg(value ORDER BY (value->>'from')||':'||(value->>'issuer')||':'||gc_authority.ref_key(value->'child')),'[]') INTO dependencies FROM jsonb_array_elements(dependencies);
 SELECT coalesce(jsonb_agg(value ORDER BY value->>'id'),'[]') INTO principals FROM jsonb_array_elements(principals);
 SELECT coalesce(jsonb_agg(value ORDER BY value->>'id'),'[]') INTO groups FROM jsonb_array_elements(groups);
 SELECT coalesce(jsonb_agg(value ORDER BY (value#>>'{ref,id}')||'@'||(value#>>'{ref,version}')),'[]') INTO memberships FROM jsonb_array_elements(memberships);
 SELECT coalesce(jsonb_agg(value ORDER BY value#>>'{subject,id}'),'[]') INTO principal_groups FROM jsonb_array_elements(principal_groups);
 SELECT coalesce(jsonb_agg(value ORDER BY (value->>'kind')||':'||(value->>'id')||'@'||(value->>'version')),'[]') INTO definitions FROM jsonb_array_elements(definitions);
 SELECT coalesce(jsonb_agg(value ORDER BY (value#>>'{pin,policyId}')||'@'||(value#>>'{pin,version}')||'#'||(value#>>'{pin,hash}')),'[]') INTO policies FROM jsonb_array_elements(policies);
 SELECT coalesce(jsonb_agg(value ORDER BY gc_authority.ref_key(value->'ref')),'[]') INTO grants FROM jsonb_array_elements(grants);
 SELECT coalesce(jsonb_agg(value ORDER BY (value#>>'{ref,id}')||'@'||(value#>>'{ref,version}')),'[]') INTO uses FROM jsonb_array_elements(uses);
 SELECT coalesce(jsonb_agg(value ORDER BY value#>>'{identity,identity_id}'),'[]') INTO identity_inventory FROM jsonb_array_elements(identity_inventory);
 session_dto:=jsonb_build_object('formatVersion',1,'sessionId',auth.session_id,'sessionVersion',auth.session_version,'identityId',auth.identity_id,'tenantId',auth.tenant_id,'generation',auth.generation::text,'authnFenceEpoch',auth.authn_fence_epoch::text,'issuingRegistrationId',auth.issuing_registration_id,'issuerRegistrationId',auth.issuer_registration_id,'identityBindingId',auth.identity_binding_id,'authenticatedAt',gc_authority.utc(auth.authenticated_at),'issuedAt',gc_authority.utc(auth.issued_at),'expiresAt',gc_authority.utc(auth.expires_at));
 SELECT sum(octet_length(gc_authority.canonical(x))) INTO proof_bytes FROM unnest(ARRAY[principals,groups,memberships,principal_groups,grants,uses,parents,dependencies,lifecycle,definitions,partitions,session_dto])x;PERFORM gc_authority.require(proof_bytes<=2097152,'54000');
 out_value:=jsonb_build_object('formatVersion',1,'kind','inactive-human-candidate-closure','contentAuthority',false,'session',session_dto,'snapshot',jsonb_build_object('tenantId',auth.tenant_id,'generation',th.generation::text,'authorityEpoch',th.authority_epoch::text,'registryId',th.registry_id,'registryVersion',th.registry_version,'registryDigest',th.registry_digest,'asOf',gc_authority.utc(as_of),'identityRevisionDigest',gc_authority.hash(identity_inventory)),'selectors',selectors,'partitions',partitions,'parents',parents,'dependencies',dependencies,'principals',principals,'groups',groups,'memberships',memberships,'principalGroups',principal_groups,'definitions',definitions,'policies',policies,'grants',grants,'elevationUses',uses,'lifecycleHeads',lifecycle);
 out_value:=jsonb_set(out_value,'{snapshot,closureDigest}',to_jsonb(gc_authority.hash(out_value)));
 metrics:=jsonb_build_object('selectors',jsonb_array_length(selectors),'partitions',jsonb_array_length(partitions),'dependencyEdges',(SELECT count(DISTINCT(value->>'from',value->>'issuer')) FROM jsonb_array_elements(dependencies)),'dependencyReferences',jsonb_array_length(dependencies),'dependencyDepth',depth,'canonicalBytes',0,'jsonNodes',0,'maxDepth',0,'policies',jsonb_array_length(policies),'policyBytes',policy_bytes,'policyRules',policy_rules,'expressionNodes',expression_nodes,'ordinaryOrigins',origins,'connectedRecords',connected,'principals',jsonb_array_length(principals),'directGroupsMaximum',direct_max,'proofBytes',proof_bytes);
 out_value:=out_value||jsonb_build_object('metrics',metrics);physical:=gc_authority.json_measure(out_value);out_value:=jsonb_set(jsonb_set(out_value,'{metrics,jsonNodes}',to_jsonb(physical[1])),'{metrics,maxDepth}',to_jsonb(physical[2]));
 FOR round IN 1..4 LOOP canonical_bytes:=octet_length(gc_authority.canonical(out_value));EXIT WHEN canonical_bytes=previous_bytes;previous_bytes:=canonical_bytes;out_value:=jsonb_set(out_value,'{metrics,canonicalBytes}',to_jsonb(canonical_bytes));END LOOP;
 PERFORM gc_authority.require(canonical_bytes=octet_length(gc_authority.canonical(out_value)) AND canonical_bytes<=8388608 AND physical[1]<=262144 AND physical[2]<=32,'54000');PERFORM gc_authority.tick();check_auth:=gc_authn.foundation_session_v1(session_hash);PERFORM gc_authority.require(check_auth IS NOT DISTINCT FROM auth,'28000');
 PERFORM set_config('gc.tenant_id',coalesce(old_t,''),true);PERFORM set_config('gc.actor_id',coalesce(old_a,''),true);RETURN out_value;
EXCEPTION WHEN OTHERS THEN PERFORM set_config('gc.tenant_id',coalesce(old_t,''),true);PERFORM set_config('gc.actor_id',coalesce(old_a,''),true);RAISE;
END $$;

CREATE FUNCTION gc_authority.scope_literal_subset(child jsonb,parent jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT gc_authority.scope_tenant(child)=gc_authority.scope_tenant(parent) AND CASE WHEN parent->>'kind'='tenant' THEN true WHEN child->>'kind'='tenant' THEN false WHEN parent->>'kind'='resource' THEN child=parent WHEN child->>'kind'='domain' AND child->>'domainId'=parent->>'domainId' THEN NOT (child->>'includeDescendants')::boolean OR (parent->>'includeDescendants')::boolean ELSE true END $$;
CREATE FUNCTION gc_authority.claim_insert_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE b gc_authority.write_bindings;BEGIN
 b:=gc_authority.binding();PERFORM gc_authority.require(NEW.transaction_id=b.transaction_id AND NEW.tenant_id=b.tenant_id AND NOT EXISTS(SELECT 1 FROM gc_authority.write_lock_claims WHERE transaction_id=b.transaction_id AND phase='sealed'),'23514');
 IF NEW.phase='sealed' THEN PERFORM gc_authority.require(NEW.object_id=b.tenant_id AND EXISTS(SELECT 1 FROM gc_authority.write_lock_claims WHERE transaction_id=b.transaction_id AND phase='configuration' AND kind='authn-tenant' AND object_id=b.tenant_id),'23514');END IF;RETURN NEW;END $$;
CREATE TRIGGER authority_claim_binding BEFORE INSERT ON gc_authority.write_lock_claims FOR EACH ROW EXECUTE FUNCTION gc_authority.claim_insert_guard();
CREATE FUNCTION gc_authority.binding_insert_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ BEGIN
 PERFORM gc_authority.owner_check();PERFORM gc_authority.require(NEW.transaction_id=pg_current_xact_id() AND NEW.backend_pid=pg_backend_pid() AND NEW.owner_role_oid=session_user::regrole::oid AND NEW.tenant_id=public.gc_tenant() AND NEW.started_at=transaction_timestamp() AND NEW.deadline_at=transaction_timestamp()+interval '30 seconds' AND EXISTS(SELECT 1 FROM gc_authority.tenant_heads WHERE tenant_id=NEW.tenant_id AND authority_epoch=NEW.epoch_before),'23514');RETURN NEW;END $$;
CREATE TRIGGER authority_binding_source BEFORE INSERT ON gc_authority.write_bindings FOR EACH ROW EXECUTE FUNCTION gc_authority.binding_insert_guard();
CREATE FUNCTION gc_authority.source_head_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE n jsonb:=to_jsonb(NEW);o jsonb:=to_jsonb(OLD);body jsonb;actual boolean;BEGIN
 PERFORM gc_authority.require(TG_OP<>'DELETE' AND pg_trigger_depth()>=2,'23514');
 IF TG_TABLE_NAME='identity_heads' THEN
 body:=jsonb_build_object('identityId',n->'identity_id','present',n->'present','canonicalIssuer',n->'canonical_issuer','canonicalSubject',n->'canonical_subject','active',n->'active');
 SELECT EXISTS(SELECT 1 FROM public.identities x WHERE x.id=(n->>'identity_id')::uuid AND (x.issuer,x.subject,x.active) IS NOT DISTINCT FROM (n->>'canonical_issuer',n->>'canonical_subject',(n->>'active')::boolean)) INTO actual;
 PERFORM gc_authority.require((n->>'present')::boolean=actual AND ((n->>'present')::boolean OR NOT EXISTS(SELECT 1 FROM public.identities WHERE id=(n->>'identity_id')::uuid)),'23514');
 ELSE
 body:=jsonb_build_object('tenantId',n->'tenant_id','identityId',n->'identity_id','present',n->'present','active',n->'active');SELECT EXISTS(SELECT 1 FROM public.memberships x WHERE x.tenant_id=(n->>'tenant_id')::uuid AND x.identity_id=(n->>'identity_id')::uuid AND x.active=(n->>'active')::boolean) INTO actual;
 PERFORM gc_authority.require((n->>'present')::boolean=actual AND ((n->>'present')::boolean OR NOT EXISTS(SELECT 1 FROM public.memberships WHERE tenant_id=(n->>'tenant_id')::uuid AND identity_id=(n->>'identity_id')::uuid)),'23514');END IF;
 PERFORM gc_authority.require(n->>'row_digest'=gc_authority.hash(body) AND ((TG_OP='INSERT' AND n->>'revision'='1') OR (TG_OP='UPDATE' AND (n->>'revision')::numeric=(o->>'revision')::numeric+1 AND n->'identity_id'=o->'identity_id' AND n->'tenant_id' IS NOT DISTINCT FROM o->'tenant_id' AND n->'membership_id' IS NOT DISTINCT FROM o->'membership_id')),'23514');RETURN NEW;END $$;
CREATE TRIGGER authority_identity_source BEFORE INSERT OR UPDATE OR DELETE ON gc_authority.identity_heads FOR EACH ROW EXECUTE FUNCTION gc_authority.source_head_guard();
CREATE TRIGGER authority_member_source BEFORE INSERT OR UPDATE OR DELETE ON gc_authority.tenant_member_heads FOR EACH ROW EXECUTE FUNCTION gc_authority.source_head_guard();
CREATE TRIGGER authority_public_identity_no_truncate BEFORE TRUNCATE ON public.identities FOR EACH STATEMENT EXECUTE FUNCTION gc_authority.immutable();
CREATE TRIGGER authority_public_member_no_truncate BEFORE TRUNCATE ON public.memberships FOR EACH STATEMENT EXECUTE FUNCTION gc_authority.immutable();
CREATE TRIGGER authority_identity_no_truncate BEFORE TRUNCATE ON gc_authority.identity_heads FOR EACH STATEMENT EXECUTE FUNCTION gc_authority.immutable();
CREATE TRIGGER authority_member_no_truncate BEFORE TRUNCATE ON gc_authority.tenant_member_heads FOR EACH STATEMENT EXECUTE FUNCTION gc_authority.immutable();
-- Companion rows can only complete the issuance/publication being written now.
-- Adding a new pin/deny marker to an old immutable publication is not publication.
CREATE FUNCTION gc_authority.companion_insert_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE j jsonb:=to_jsonb(NEW);i uuid;v integer;h integer;k text;BEGIN
 IF TG_TABLE_NAME IN('definition_versions','policy_versions','role_policy_pins','responsibility_role_pins','policy_deny_intents') THEN
 CASE TG_TABLE_NAME WHEN 'definition_versions' THEN i:=(j->>'id')::uuid;v:=(j->>'version')::int;k:=j->>'kind';WHEN 'policy_versions' THEN i:=(j->>'policy_id')::uuid;v:=(j->>'version')::int;k:='policy';WHEN 'policy_deny_intents' THEN i:=(j->>'policy_id')::uuid;v:=(j->>'policy_version')::int;k:='policy';WHEN 'role_policy_pins' THEN i:=(j->>'role_id')::uuid;v:=(j->>'role_version')::int;k:='role';ELSE i:=(j->>'type_id')::uuid;v:=(j->>'type_version')::int;k:='responsibility-type';END CASE;
 PERFORM gc_authority.require(EXISTS(SELECT 1 FROM gc_authority.definition_heads WHERE tenant_id=(j->>'tenant_id')::uuid AND id=i AND kind=k AND definition_version=v AND xmin=pg_current_xact_id()::xid),'23514');
 ELSIF TG_TABLE_NAME IN('grant_human_beneficiaries','grant_group_beneficiaries','ordinary_role_origins','responsibility_origins','connected_parents') THEN i:=coalesce((j->>'grant_id')::uuid,(j->>'child_id')::uuid);PERFORM gc_authority.require(EXISTS(SELECT 1 FROM gc_authority.grant_heads WHERE tenant_id=(j->>'tenant_id')::uuid AND id=i AND head_version=1 AND xmin=pg_current_xact_id()::xid),'23514');END IF;RETURN NEW;END $$;
CREATE FUNCTION gc_authority.use_issue_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,gc_authority,pg_temp SET row_security=on AS $$ DECLARE s gc_authn.sessions;BEGIN
 SELECT * INTO s FROM gc_authn.sessions WHERE id=NEW.protected_session_id;PERFORM gc_authority.require((s.identity_id,s.selected_tenant_id,s.version,s.generation) IS NOT DISTINCT FROM (NEW.identity_id,NEW.tenant_id,NEW.protected_session_version,NEW.generation) AND s.revoked_at IS NULL AND s.expires_at>clock_timestamp(),'23514');PERFORM gc_authority.require(EXISTS(SELECT 1 FROM gc_authn.session_provenance p WHERE p.session_id=s.id AND (p.identity_id,p.generation,p.session_hash)=(s.identity_id,s.generation,s.session_hash)),'23514');RETURN NEW;END $$;
CREATE TRIGGER authority_use_current_session BEFORE INSERT ON gc_authority.elevation_uses FOR EACH ROW EXECUTE FUNCTION gc_authority.use_issue_guard();
-- Privilege/forced-RLS closure is explicit and does not alter legacy grants.
DO $$ DECLARE t text;BEGIN
 FOREACH t IN ARRAY ARRAY['tenant_heads','tenant_member_heads','definition_heads','definition_versions','policy_versions','role_policy_pins','responsibility_role_pins','policy_deny_intents','group_memberships','grant_heads','grant_human_beneficiaries','grant_group_beneficiaries','ordinary_role_origins','responsibility_origins','connected_parents','elevation_uses','lifecycle_revisions','projection_measures','write_bindings','write_lock_claims'] LOOP
 EXECUTE format('ALTER TABLE gc_authority.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE gc_authority.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY authority_tenant ON gc_authority.%I USING(tenant_id=public.gc_tenant()) WITH CHECK(tenant_id=public.gc_tenant())',t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['definition_heads','definition_versions','policy_versions','role_policy_pins','responsibility_role_pins','policy_deny_intents','group_memberships','grant_heads','grant_human_beneficiaries','grant_group_beneficiaries','ordinary_role_origins','responsibility_origins','connected_parents','elevation_uses','lifecycle_revisions','projection_measures'] LOOP
 EXECUTE format('CREATE TRIGGER a_authority_statement BEFORE INSERT OR UPDATE OR DELETE ON gc_authority.%I FOR EACH STATEMENT EXECUTE FUNCTION gc_authority.write_statement()',t);
 EXECUTE format('CREATE TRIGGER a_authority_claim BEFORE INSERT OR UPDATE OR DELETE ON gc_authority.%I FOR EACH ROW EXECUTE FUNCTION gc_authority.write_claim_guard()',t);
 EXECUTE format('CREATE TRIGGER a_authority_companion BEFORE INSERT ON gc_authority.%I FOR EACH ROW EXECUTE FUNCTION gc_authority.companion_insert_guard()',t);
 EXECUTE format('CREATE TRIGGER b_authority_row BEFORE INSERT OR UPDATE OR DELETE ON gc_authority.%I FOR EACH ROW EXECUTE FUNCTION gc_authority.write_row()',t);
 EXECUTE format('CREATE CONSTRAINT TRIGGER authority_complete AFTER INSERT OR UPDATE ON gc_authority.%I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION gc_authority.deferred_complete()',t);
 EXECUTE format('CREATE TRIGGER authority_no_truncate BEFORE TRUNCATE ON gc_authority.%I FOR EACH STATEMENT EXECUTE FUNCTION gc_authority.immutable()',t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['foundation_root','installation_receipts','registries','write_bindings','write_lock_claims'] LOOP
 EXECUTE format('CREATE TRIGGER authority_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON gc_authority.%I FOR EACH STATEMENT EXECUTE FUNCTION gc_authority.immutable()',t);
 END LOOP;
END $$;
CREATE CONSTRAINT TRIGGER authority_binding_complete AFTER INSERT ON gc_authority.write_bindings DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION gc_authority.deferred_complete();
REVOKE ALL ON ALL TABLES IN SCHEMA gc_authority FROM PUBLIC,gc_app;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA gc_authority FROM PUBLIC,gc_app;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA gc_authority FROM PUBLIC,gc_app;
DO $$ DECLARE r record;BEGIN FOR r IN SELECT typname FROM pg_type WHERE typnamespace='gc_authority'::regnamespace AND typtype='c' LOOP EXECUTE format('REVOKE ALL ON TYPE gc_authority.%I FROM PUBLIC,gc_app',r.typname);END LOOP;END $$;
